        else if (dto.Vins != null && dto.Vins.Count > 0) items.AddRange(dto.Vins.Select(v => new RedeemItemInputDto(v)));

        if (items.Count == 0)
            throw new InvalidOperationException("Cần ít nhất 1 VIN trong yêu cầu giải chấp.");

