    {
        declarationNo = declarationNo.Trim().ToUpperInvariant();
        var cd = await db.CustomsDeclarations.FirstOrDefaultAsync(d => d.OrgId == Org && d.DeclarationNo == declarationNo);
        if (cd is null) return null;

