            r.RoNoUser,
            r.DealerCode,
            r.Vin,
            r.Model,
            r.PlateNo,
            r.CustomerName,
            r.CustomerPhone,
            r.RoType,
            r.ServiceAdvisor,
            r.Technician,
            r.OdoKm,
            r.CheckInDate,
            r.ExpectedDeliveryDate,
            r.ActualDeliveryDate,
            r.TotalLaborAmount,
            r.TotalPartAmount,
            r.DiscountAmount,
            r.TotalVatAmount,
            r.TotalAmount,
            r.PaymentStatus,
            r.PaymentMethod,
            r.Status,
            r.CreatedAt,
            serviceLineCount = db.RepairOrderServiceLines.Count(l => l.OrgId == r.OrgId && l.RepairOrderId == r.Id && l.Status != "Cancelled"),
            partLineCount = db.RepairOrderPartLines.Count(l => l.OrgId == r.OrgId && l.RepairOrderId == r.Id && l.Status != "Cancelled")
        }).ToListAsync();

        return new { count = items.Count, items };
    }

