    public async Task<object?> CreateRoFromAppointmentAsync(string appNo, CreateRoFromAppointmentDto? dto)
    {
        var no = appNo.Trim().ToUpperInvariant();
        var app = await db.ServiceAppointments.FirstOrDefaultAsync(a => a.OrgId == Org && a.AppNo == no);
        if (app is null) return null;

        if (app.Status is "Completed" or "Cancelled" or "NoShow")
            throw new InvalidOperationException($"Lịch hẹn đang ở trạng thái '{app.Status}', không thể mở lệnh sửa chữa RO.");

        if (!string.IsNullOrWhiteSpace(app.RoNo) && await db.RepairOrders.AnyAsync(r => r.OrgId == Org && r.RoNo == app.RoNo))
            throw new InvalidOperationException($"Lịch hẹn {app.AppNo} đã liên kết với lệnh sửa chữa {app.RoNo}.");

        var appServices = await db.ServiceAppointmentServiceLines.Where(s => s.OrgId == Org && s.ServiceAppointmentId == app.Id && s.Status != "Cancelled").ToListAsync();
        var appParts = await db.ServiceAppointmentPartLines.Where(p => p.OrgId == Org && p.ServiceAppointmentId == app.Id && p.Status != "Cancelled").ToListAsync();

        var serviceItems = appServices.Select(s => new RepairOrderServiceItemInputDto(
            s.SerCode,
            s.SerName,
            s.ServiceType,
            s.StandardHours,
            s.LaborPrice,
            s.Discount,
            s.LaborAmount,
            s.Technician ?? dto?.Technician ?? app.Technician,
            s.Remark
        )).ToList();

        var partItems = appParts.Select(p => new RepairOrderPartItemInputDto(
            p.PartCode,
            p.PartName,
            p.Unit,
            p.Quantity,
            p.UnitPrice,
            p.Discount,
            p.TotalAmount,
            p.PaymentType,
            p.Remark
        )).ToList();

        var createRoDto = new CreateRepairOrderDto(
            DealerCode: app.DealerCode,
            Vin: app.Vin,
            ServiceItems: serviceItems,
            PartItems: partItems,
            RoNo: dto?.RoNo,
            RoNoUser: dto?.RoNoUser,
            Model: app.Model,
            EngineNo: app.EngineNo,
            PlateNo: app.PlateNo,
            CustomerName: app.CustomerName,
            CustomerPhone: app.CustomerPhone,
            RoType: app.ServiceType,
            ServiceAdvisor: dto?.ServiceAdvisor ?? app.ServiceAdvisor,
            Technician: dto?.Technician ?? app.Technician,
            OdoKm: dto?.OdoKm ?? 0,
            FuelLevel: dto?.FuelLevel ?? "1/2",
            CarStatus: dto?.CarStatus ?? "Tiếp nhận xe từ Lịch hẹn dịch vụ",
            CustomerRequest: app.CustomerRequest,
            DiagnosisNotes: $"Tạo tự động từ Lịch hẹn {app.AppNo}",
            CheckInDate: DateTime.Now,
            ExpectedDeliveryDate: DateTime.Now.AddMinutes(app.EstimatedDurationMinutes > 0 ? app.EstimatedDurationMinutes : 60),
            DiscountAmount: dto?.DiscountAmount ?? 0,
            VatRate: dto?.VatRate ?? 10,
            PaymentMethod: dto?.PaymentMethod ?? "Cash",
            Remark: dto?.Remark ?? $"Lệnh sửa chữa liên kết Lịch hẹn {app.AppNo}",
            CreatedBy: dto?.CreatedBy ?? app.CreatedBy
        );

        var roResult = await CreateRepairOrderAsync(createRoDto);
        var roNoProp = roResult.GetType().GetProperty("RoNo")?.GetValue(roResult)?.ToString();
        var generatedRoNo = !string.IsNullOrWhiteSpace(dto?.RoNo) ? dto.RoNo.Trim().ToUpperInvariant() : roNoProp;

        app.RoNo = generatedRoNo;
        app.Status = "InService";
        if (app.CheckedInAt == null)
        {
            app.CheckedInBy = dto?.CreatedBy ?? "Advisor";
            app.CheckedInAt = DateTime.Now;
        }

        Log(app.Vin, "RepairOrderCreatedFromApp", $"AppNo={app.AppNo}, RoNo={app.RoNo}, Dealer={app.DealerCode}");
        await db.SaveChangesAsync();

        return new
        {
            appointment = await GetServiceAppointmentAsync(app.AppNo),
            repairOrder = roResult
        };
    }

    public async Task<object?> GetVehicleAppointmentHistoryAsync(string vin)
    {
        var vVin = vin.Trim().ToUpperInvariant();
        var vehicle = await db.Vehicles.FirstOrDefaultAsync(v => v.OrgId == Org && v.Vin == vVin);
        if (vehicle is null) return null;

        var apps = await db.ServiceAppointments.Where(a => a.OrgId == Org && a.Vin == vVin)
            .OrderByDescending(a => a.AppointmentDate)
            .ThenByDescending(a => a.CreatedAt)
            .ToListAsync();

        var appIds = apps.Select(a => a.Id).ToList();
        var sLines = await db.ServiceAppointmentServiceLines.Where(s => s.OrgId == Org && appIds.Contains(s.ServiceAppointmentId)).ToListAsync();
        var pLines = await db.ServiceAppointmentPartLines.Where(p => p.OrgId == Org && appIds.Contains(p.ServiceAppointmentId)).ToListAsync();
        var events = await db.Events.Where(e => e.OrgId == Org && e.Vin == vVin && e.Kind.StartsWith("ServiceAppointment"))
            .OrderByDescending(e => e.At)
            .ToListAsync();

        return new
        {
            vehicle = new
            {
                vehicle.Vin,
                vehicle.Model,
                vehicle.EngineNo,
                vehicle.Color,
                vehicle.ModelYear,
                status = vehicle.Status.ToString(),
                vehicle.PlateNo,
                vehicle.OwnerName,
                vehicle.OwnerPhone,
                vehicle.LastAppointmentNo,
                vehicle.LastAppointmentDate,
                vehicle.LastRoNo,
                vehicle.LastRoDate,
                vehicle.LastOdoKm
            },
            totalAppointments = apps.Count,
            appointments = apps.Select(a => new
            {
                a.Id,
                a.AppNo,
                a.AppNoUser,
                a.DealerCode,
                a.ServiceType,
                a.AppointmentDate,
                a.AppointmentTime,
                a.EstimatedDurationMinutes,
                a.ServiceAdvisor,
                a.Technician,
                a.CustomerRequest,
                a.TotalEstimatedLabor,
                a.TotalEstimatedParts,
                a.TotalEstimatedAmount,
                a.Status,
                a.RoNo,
                a.CreatedAt,
                a.ConfirmedAt,
                a.CheckedInAt,
                a.CompletedAt,
                a.CancelledAt,
                a.CancelReason,
                a.NoShowAt,
                serviceLines = sLines.Where(s => s.ServiceAppointmentId == a.Id).Select(s => new { s.Id, s.SerCode, s.SerName, s.ServiceType, s.StandardHours, s.LaborPrice, s.Discount, s.LaborAmount, s.Technician, s.Status, s.Remark }),
                partLines = pLines.Where(p => p.ServiceAppointmentId == a.Id).Select(p => new { p.Id, p.PartCode, p.PartName, p.Unit, p.Quantity, p.UnitPrice, p.Discount, p.TotalAmount, p.PaymentType, p.Status, p.Remark })
            }),
            events = events.Select(e => new
            {
                e.Kind,
                e.Note,
                e.At
            })
        };
    }

    public async Task<object> GetServiceAppointmentSummaryAsync()
    {
        var apps = await db.ServiceAppointments.Where(a => a.OrgId == Org).ToListAsync();
        var today = DateTime.Today;
        var tomorrow = today.AddDays(1);

        var todayCount = apps.Count(a => a.AppointmentDate.Date == today);
        var upcomingCount = apps.Count(a => a.AppointmentDate.Date >= today && a.Status is "Booked" or "Confirmed");
        var completedCount = apps.Count(a => a.Status == "Completed");
        var noShowCount = apps.Count(a => a.Status == "NoShow");
        var cancelledCount = apps.Count(a => a.Status == "Cancelled");

        var byStatus = apps.GroupBy(a => a.Status).Select(g => new
        {
            status = g.Key,
            count = g.Count(),
            totalEstimatedAmount = g.Sum(a => a.TotalEstimatedAmount)
        }).ToList();

        var byType = apps.GroupBy(a => a.ServiceType).Select(g => new
        {
            serviceType = g.Key,
            count = g.Count(),
            totalEstimatedAmount = g.Sum(a => a.TotalEstimatedAmount)
        }).ToList();

        var byDealer = apps.GroupBy(a => a.DealerCode).Select(g => new
        {
            dealerCode = g.Key,
            count = g.Count(),
            totalEstimatedAmount = g.Sum(a => a.TotalEstimatedAmount)
        }).ToList();

        var totalValid = apps.Count(a => a.Status != "Cancelled");
        var completionRate = totalValid > 0 ? Math.Round((decimal)completedCount / totalValid * 100, 1) : 0;
        var noShowRate = totalValid > 0 ? Math.Round((decimal)noShowCount / totalValid * 100, 1) : 0;

        return new
        {
            totalAppointments = apps.Count,
            todayAppointments = todayCount,
            upcomingAppointments = upcomingCount,
            completedAppointments = completedCount,
            noShowAppointments = noShowCount,
            cancelledAppointments = cancelledCount,
            completionRatePercent = completionRate,
            noShowRatePercent = noShowRate,
            totalEstimatedLabor = apps.Where(a => a.Status != "Cancelled").Sum(a => a.TotalEstimatedLabor),
            totalEstimatedParts = apps.Where(a => a.Status != "Cancelled").Sum(a => a.TotalEstimatedParts),
            totalEstimatedAmount = apps.Where(a => a.Status != "Cancelled").Sum(a => a.TotalEstimatedAmount),
            byStatus,
            byType,
            byDealer
        };
    }

    public async Task<object> CreateTechnicalBulletinAsync(CreateTechnicalBulletinDto dto)
    {
        var count = await db.TechnicalBulletins.CountAsync(b => b.OrgId == Org);
        var bulletinNo = !string.IsNullOrWhiteSpace(dto.BulletinNo)
            ? dto.BulletinNo.Trim().ToUpperInvariant()
            : $"TSB-{DateTime.Now:yyyyMMdd}-{count + 1:D3}";

        if (await db.TechnicalBulletins.AnyAsync(b => b.OrgId == Org && b.BulletinNo == bulletinNo))
            throw new InvalidOperationException($"Bản tin kỹ thuật {bulletinNo} đã tồn tại.");

        var b = new TechnicalBulletin
        {
            OrgId = Org,
            BulletinNo = bulletinNo,
            BulletinNoUser = dto.BulletinNoUser?.Trim(),
            Title = dto.Title.Trim(),
            Category = dto.Category?.Trim() ?? "SoftwareUpdate",
            Model = dto.Model?.Trim(),
            Severity = dto.Severity?.Trim() ?? "Medium",
            ReleaseDate = dto.ReleaseDate ?? DateTime.Now,
            ExpiryDate = dto.ExpiryDate,
            Description = dto.Description?.Trim(),
            Remedy = dto.Remedy?.Trim(),
            AttachmentFileName = dto.AttachmentFileName?.Trim(),
            AttachmentUrl = dto.AttachmentUrl?.Trim(),
            Status = "Draft",
            Remark = dto.Remark?.Trim(),
            CreatedBy = dto.CreatedBy?.Trim(),
            CreatedAt = DateTime.Now
        };

        db.TechnicalBulletins.Add(b);
        await db.SaveChangesAsync();

        var lines = new List<TechnicalBulletinLine>();
        if (dto.Items != null && dto.Items.Count > 0)
        {
            foreach (var item in dto.Items)
            {
                if (string.IsNullOrWhiteSpace(item.Vin)) continue;
                var vin = item.Vin.Trim().ToUpperInvariant();
                var v = await db.Vehicles.FirstOrDefaultAsync(x => x.OrgId == Org && x.Vin == vin);
                lines.Add(new TechnicalBulletinLine
                {
                    OrgId = Org,
                    TechnicalBulletinId = b.Id,
                    BulletinNo = b.BulletinNo,
                    Vin = vin,
                    Model = item.Model ?? v?.Model,
                    EngineNo = item.EngineNo ?? v?.EngineNo,
                    PlateNo = item.PlateNo ?? v?.PlateNo,
                    DealerCode = item.DealerCode ?? v?.DealerCode,
                    Status = "Pending",
                    Remark = item.Remark?.Trim()
                });
            }
        }
        else if (dto.Vins != null && dto.Vins.Count > 0)
        {
            foreach (var rawVin in dto.Vins)
            {
                if (string.IsNullOrWhiteSpace(rawVin)) continue;
                var vin = rawVin.Trim().ToUpperInvariant();
                var v = await db.Vehicles.FirstOrDefaultAsync(x => x.OrgId == Org && x.Vin == vin);
                lines.Add(new TechnicalBulletinLine
                {
                    OrgId = Org,
                    TechnicalBulletinId = b.Id,
                    BulletinNo = b.BulletinNo,
                    Vin = vin,
                    Model = v?.Model,
                    EngineNo = v?.EngineNo,
                    PlateNo = v?.PlateNo,
                    DealerCode = v?.DealerCode,
                    Status = "Pending"
                });
            }
        }
        else if (!string.IsNullOrWhiteSpace(dto.Model))
        {
            var matchingVehicles = await db.Vehicles.Where(v => v.OrgId == Org && v.Model.Contains(dto.Model.Trim())).ToListAsync();
            foreach (var v in matchingVehicles)
            {
                lines.Add(new TechnicalBulletinLine
                {
                    OrgId = Org,
                    TechnicalBulletinId = b.Id,
                    BulletinNo = b.BulletinNo,
                    Vin = v.Vin,
                    Model = v.Model,
                    EngineNo = v.EngineNo,
                    PlateNo = v.PlateNo,
                    DealerCode = v.DealerCode,
                    Status = "Pending"
                });
            }
        }

        if (lines.Count > 0)
        {
            db.TechnicalBulletinLines.AddRange(lines);
            b.TotalVehicleCount = lines.Count;
            await db.SaveChangesAsync();
        }

        return new
        {
            b.Id,
            b.BulletinNo,
            b.BulletinNoUser,
            b.Title,
            b.Category,
            b.Model,
            b.Severity,
            b.ReleaseDate,
            b.ExpiryDate,
            b.Description,
            b.Remedy,
            b.AttachmentFileName,
            b.AttachmentUrl,
            b.TotalVehicleCount,
            b.CompletedVehicleCount,
            b.Status,
            b.Remark,
            b.CreatedBy,
            b.CreatedAt,
            Lines = lines.Select(l => new
            {
                l.Id,
                l.BulletinNo,
                l.Vin,
                l.Model,
                l.EngineNo,
                l.PlateNo,
                l.DealerCode,
                l.Status,
                l.InspectedAt,
                l.CompletedAt,
                l.Technician,
                l.OdoKm,
                l.RoNo,
                l.ResultNotes,
                l.Remark
            })
        };
    }

    public async Task<object> ListTechnicalBulletinsAsync(string? status, string? category, string? severity, string? model, string? bulletinNo, string? vin)
    {
        var q = db.TechnicalBulletins.Where(b => b.OrgId == Org);

        if (!string.IsNullOrWhiteSpace(status))
            q = q.Where(b => b.Status == status.Trim());
        if (!string.IsNullOrWhiteSpace(category))
            q = q.Where(b => b.Category == category.Trim());
        if (!string.IsNullOrWhiteSpace(severity))
            q = q.Where(b => b.Severity == severity.Trim());
        if (!string.IsNullOrWhiteSpace(model))
            q = q.Where(b => b.Model != null && b.Model.Contains(model.Trim()));
        if (!string.IsNullOrWhiteSpace(bulletinNo))
            q = q.Where(b => b.BulletinNo.Contains(bulletinNo.Trim().ToUpperInvariant()));

        if (!string.IsNullOrWhiteSpace(vin))
        {
            var targetVin = vin.Trim().ToUpperInvariant();
            var bIds = await db.TechnicalBulletinLines
                .Where(l => l.OrgId == Org && l.Vin.Contains(targetVin))
                .Select(l => l.TechnicalBulletinId)
                .Distinct()
                .ToListAsync();
            q = q.Where(b => bIds.Contains(b.Id));
        }

        var list = await q.OrderByDescending(b => b.Id).Take(200).ToListAsync();
        var bIdsAll = list.Select(b => b.Id).ToList();
        var allLines = await db.TechnicalBulletinLines
            .Where(l => l.OrgId == Org && bIdsAll.Contains(l.TechnicalBulletinId))
            .ToListAsync();

        return list.Select(b =>
        {
            var lines = allLines.Where(l => l.TechnicalBulletinId == b.Id).ToList();
            var completedCount = lines.Count(l => l.Status == "Completed");
            var pendingCount = lines.Count(l => l.Status == "Pending" || l.Status == "Notified" || l.Status == "InProgress");
            var completionPercent = lines.Count > 0 ? Math.Round((decimal)completedCount / lines.Count * 100, 1) : 0;

            return new
            {
                b.Id,
                b.BulletinNo,
                b.BulletinNoUser,
                b.Title,
                b.Category,
                b.Model,
                b.Severity,
                b.ReleaseDate,
                b.ExpiryDate,
                b.Description,
                b.Remedy,
                b.AttachmentFileName,
                b.AttachmentUrl,
                totalVehicleCount = lines.Count,
                completedVehicleCount = completedCount,
                pendingVehicleCount = pendingCount,
                completionPercent,
                b.Status,
                b.Remark,
                b.CreatedBy,
                b.CreatedAt,
                b.PublishedBy,
                b.PublishedAt,
                b.ArchivedBy,
                b.ArchivedAt,
                b.CancelledBy,
                b.CancelledAt
            };
        });
    }

    public async Task<object?> GetTechnicalBulletinAsync(string bulletinNo)
    {
        var code = bulletinNo.Trim().ToUpperInvariant();
        var b = await db.TechnicalBulletins.FirstOrDefaultAsync(x => x.OrgId == Org && x.BulletinNo == code);
        if (b == null) return null;

        var lines = await db.TechnicalBulletinLines
            .Where(l => l.OrgId == Org && l.TechnicalBulletinId == b.Id)
            .OrderBy(l => l.Id)
            .ToListAsync();

        var completedCount = lines.Count(l => l.Status == "Completed");
        var completionPercent = lines.Count > 0 ? Math.Round((decimal)completedCount / lines.Count * 100, 1) : 0;

        return new
        {
            b.Id,
            b.BulletinNo,
            b.BulletinNoUser,
            b.Title,
            b.Category,
            b.Model,
            b.Severity,
            b.ReleaseDate,
            b.ExpiryDate,
            b.Description,
            b.Remedy,
            b.AttachmentFileName,
            b.AttachmentUrl,
            totalVehicleCount = lines.Count,
            completedVehicleCount = completedCount,
            pendingVehicleCount = lines.Count - completedCount,
            completionPercent,
            b.Status,
            b.Remark,
            b.CreatedBy,
            b.CreatedAt,
            b.PublishedBy,
            b.PublishedAt,
            b.ArchivedBy,
            b.ArchivedAt,
            b.CancelledBy,
            b.CancelledAt,
            b.CancelReason,
            Lines = lines.Select(l => new
            {
                l.Id,
                l.TechnicalBulletinId,
                l.BulletinNo,
                l.Vin,
                l.Model,
                l.EngineNo,
                l.PlateNo,
                l.DealerCode,
                l.Status,
                l.InspectedAt,
                l.CompletedAt,
                l.Technician,
                l.OdoKm,
                l.RoNo,
                l.ResultNotes,
                l.Remark
            })
        };
    }

    public async Task<object?> UpdateTechnicalBulletinHeaderAsync(string bulletinNo, UpdateTechnicalBulletinHeaderDto dto)
    {
        var code = bulletinNo.Trim().ToUpperInvariant();
        var b = await db.TechnicalBulletins.FirstOrDefaultAsync(x => x.OrgId == Org && x.BulletinNo == code);
        if (b == null) return null;

        if (b.Status is "Archived" or "Cancelled")
            throw new InvalidOperationException($"Bản tin {bulletinNo} đã ở trạng thái {b.Status}, không thể chỉnh sửa.");

        if (dto.Title != null) b.Title = dto.Title.Trim();
        if (dto.Category != null) b.Category = dto.Category.Trim();
        if (dto.Model != null) b.Model = dto.Model.Trim();
        if (dto.Severity != null) b.Severity = dto.Severity.Trim();
        if (dto.ReleaseDate != null) b.ReleaseDate = dto.ReleaseDate.Value;
        if (dto.ExpiryDate != null) b.ExpiryDate = dto.ExpiryDate.Value;
        if (dto.Description != null) b.Description = dto.Description.Trim();
        if (dto.Remedy != null) b.Remedy = dto.Remedy.Trim();
        if (dto.AttachmentFileName != null) b.AttachmentFileName = dto.AttachmentFileName.Trim();
        if (dto.AttachmentUrl != null) b.AttachmentUrl = dto.AttachmentUrl.Trim();
        if (dto.Remark != null) b.Remark = dto.Remark.Trim();

        await db.SaveChangesAsync();
        return await GetTechnicalBulletinAsync(code);
    }

    public async Task<object?> TechnicalBulletinTransitionAsync(string bulletinNo, string action, TechnicalBulletinTransitionDto? dto)
    {
        var code = bulletinNo.Trim().ToUpperInvariant();
        var b = await db.TechnicalBulletins.FirstOrDefaultAsync(x => x.OrgId == Org && x.BulletinNo == code);
        if (b == null) return null;

        var act = action.Trim().ToLowerInvariant();
        switch (act)
        {
            case "publish":
            case "submit":
                if (b.Status is not ("Draft" or "Suspended"))
                    throw new InvalidOperationException($"Bản tin đang ở trạng thái {b.Status}, chỉ có thể Publish từ Draft hoặc Suspended.");
                b.Status = "Published";
                b.PublishedBy = dto?.User?.Trim() ?? "OEM.TechnicalDirector";
                b.PublishedAt = DateTime.Now;

                var lines = await db.TechnicalBulletinLines.Where(l => l.OrgId == Org && l.TechnicalBulletinId == b.Id).ToListAsync();
                foreach (var l in lines)
                {
                    if (l.Status == "Pending") l.Status = "Notified";
                    Log(l.Vin, "BulletinPublished", $"Phát hành bản tin {b.BulletinNo} ({b.Category}): {b.Title}");
                }
                break;

            case "suspend":
                if (b.Status != "Published")
                    throw new InvalidOperationException($"Chỉ có thể tạm dừng bản tin đang Published.");
                b.Status = "Suspended";
                if (dto?.Note != null) b.Remark = (b.Remark != null ? b.Remark + " | " : "") + $"[Tạm dừng: {dto.Note}]";
                break;

            case "archive":
            case "close":
                if (b.Status is not ("Published" or "Suspended"))
                    throw new InvalidOperationException($"Chỉ có thể lưu trữ/đóng bản tin Published hoặc Suspended.");
                b.Status = "Archived";
                b.ArchivedBy = dto?.User?.Trim() ?? "OEM.ServiceManager";
                b.ArchivedAt = DateTime.Now;
                if (dto?.Note != null) b.Remark = (b.Remark != null ? b.Remark + " | " : "") + $"[Lưu trữ: {dto.Note}]";
                break;

            case "cancel":
                if (b.Status is "Archived" or "Cancelled")
                    throw new InvalidOperationException($"Bản tin đã ở trạng thái {b.Status}.");
                b.Status = "Cancelled";
                b.CancelledBy = dto?.User?.Trim() ?? "Admin";
                b.CancelledAt = DateTime.Now;
                b.CancelReason = dto?.Reason?.Trim() ?? dto?.Note?.Trim() ?? "Hủy phát hành bản tin";
                break;

            default:
                throw new InvalidOperationException($"Hành động {action} không được hỗ trợ.");
        }

        await db.SaveChangesAsync();
        return await GetTechnicalBulletinAsync(code);
    }

    public async Task<object?> UpdateTechnicalBulletinLineAsync(string bulletinNo, string vin, UpdateTechnicalBulletinLineDto dto)
    {
        var code = bulletinNo.Trim().ToUpperInvariant();
        var targetVin = vin.Trim().ToUpperInvariant();

        var b = await db.TechnicalBulletins.FirstOrDefaultAsync(x => x.OrgId == Org && x.BulletinNo == code);
        if (b == null) return null;

        var line = await db.TechnicalBulletinLines.FirstOrDefaultAsync(l => l.OrgId == Org && l.TechnicalBulletinId == b.Id && l.Vin == targetVin);
        if (line == null) return null;

        if (dto.DealerCode != null) line.DealerCode = dto.DealerCode.Trim();
        if (dto.PlateNo != null) line.PlateNo = dto.PlateNo.Trim();
        if (dto.Technician != null) line.Technician = dto.Technician.Trim();
        if (dto.OdoKm != null) line.OdoKm = dto.OdoKm;
        if (dto.RoNo != null) line.RoNo = dto.RoNo.Trim();
        if (dto.ResultNotes != null) line.ResultNotes = dto.ResultNotes.Trim();
        if (dto.Remark != null) line.Remark = dto.Remark.Trim();
        if (dto.Status != null) line.Status = dto.Status.Trim();

        await db.SaveChangesAsync();
        return line;
    }

    public async Task<object?> CompleteTechnicalBulletinLineAsync(string bulletinNo, string vin, CompleteBulletinLineDto dto)
    {
        var code = bulletinNo.Trim().ToUpperInvariant();
        var targetVin = vin.Trim().ToUpperInvariant();

        var b = await db.TechnicalBulletins.FirstOrDefaultAsync(x => x.OrgId == Org && x.BulletinNo == code);
        if (b == null) return null;

        if (b.Status == "Cancelled")
            throw new InvalidOperationException($"Bản tin {bulletinNo} đã bị hủy.");

        var line = await db.TechnicalBulletinLines.FirstOrDefaultAsync(l => l.OrgId == Org && l.TechnicalBulletinId == b.Id && l.Vin == targetVin);
        if (line == null) return null;

        line.Status = "Completed";
        line.CompletedAt = dto.CompletedAt ?? DateTime.Now;
        line.InspectedAt ??= line.CompletedAt;
        if (dto.Technician != null) line.Technician = dto.Technician.Trim();
        if (dto.OdoKm != null) line.OdoKm = dto.OdoKm;
        if (dto.RoNo != null) line.RoNo = dto.RoNo.Trim();
        if (dto.DealerCode != null) line.DealerCode = dto.DealerCode.Trim();
        if (dto.ResultNotes != null) line.ResultNotes = dto.ResultNotes.Trim();
        if (dto.Remark != null) line.Remark = dto.Remark.Trim();

        // Cập nhật thông tin trên Vehicle
        var vehicle = await db.Vehicles.FirstOrDefaultAsync(v => v.OrgId == Org && v.Vin == targetVin);
        if (vehicle != null)
        {
            vehicle.LastBulletinNo = b.BulletinNo;
            vehicle.LastBulletinDate = line.CompletedAt;
            if (dto.OdoKm.HasValue && dto.OdoKm.Value > (vehicle.LastOdoKm ?? 0))
                vehicle.LastOdoKm = dto.OdoKm.Value;
        }

        // Cập nhật số lượng completed trên header
        var allLines = await db.TechnicalBulletinLines.Where(l => l.OrgId == Org && l.TechnicalBulletinId == b.Id).ToListAsync();
        b.CompletedVehicleCount = allLines.Count(l => l.Status == "Completed");

        Log(targetVin, "BulletinCompleted", $"Hoàn tất bản tin TSB {b.BulletinNo} ({b.Category}) tại xưởng: {line.ResultNotes ?? "Đã xử lý theo hướng dẫn TSB"}");

        await db.SaveChangesAsync();
        return line;
    }

    public async Task<object?> AddTechnicalBulletinLinesAsync(string bulletinNo, List<TechnicalBulletinItemInputDto> items)
    {
        var code = bulletinNo.Trim().ToUpperInvariant();
        var b = await db.TechnicalBulletins.FirstOrDefaultAsync(x => x.OrgId == Org && x.BulletinNo == code);
        if (b == null) return null;

        if (b.Status is "Archived" or "Cancelled")
            throw new InvalidOperationException($"Bản tin {bulletinNo} đã ở trạng thái {b.Status}, không thể bổ sung xe.");

        var existingVins = await db.TechnicalBulletinLines
            .Where(l => l.OrgId == Org && l.TechnicalBulletinId == b.Id)
            .Select(l => l.Vin)
            .ToListAsync();

        var newLines = new List<TechnicalBulletinLine>();
        foreach (var item in items)
        {
            if (string.IsNullOrWhiteSpace(item.Vin)) continue;
            var vin = item.Vin.Trim().ToUpperInvariant();
            if (existingVins.Contains(vin)) continue;

            var v = await db.Vehicles.FirstOrDefaultAsync(x => x.OrgId == Org && x.Vin == vin);
            newLines.Add(new TechnicalBulletinLine
            {
                OrgId = Org,
                TechnicalBulletinId = b.Id,
                BulletinNo = b.BulletinNo,
                Vin = vin,
                Model = item.Model ?? v?.Model,
                EngineNo = item.EngineNo ?? v?.EngineNo,
                PlateNo = item.PlateNo ?? v?.PlateNo,
                DealerCode = item.DealerCode ?? v?.DealerCode,
                Status = b.Status == "Published" ? "Notified" : "Pending",
                Remark = item.Remark?.Trim()
            });

            if (b.Status == "Published")
                Log(vin, "BulletinPublished", $"Phát hành bản tin {b.BulletinNo} ({b.Category}): {b.Title}");
        }

        if (newLines.Count > 0)
        {
            db.TechnicalBulletinLines.AddRange(newLines);
            b.TotalVehicleCount += newLines.Count;
            await db.SaveChangesAsync();
        }

        return await GetTechnicalBulletinAsync(code);
    }

    public async Task<object?> RemoveTechnicalBulletinLineAsync(string bulletinNo, string vin)
    {
        var code = bulletinNo.Trim().ToUpperInvariant();
        var targetVin = vin.Trim().ToUpperInvariant();

        var b = await db.TechnicalBulletins.FirstOrDefaultAsync(x => x.OrgId == Org && x.BulletinNo == code);
        if (b == null) return null;

        if (b.Status is "Archived" or "Cancelled")
            throw new InvalidOperationException($"Bản tin {bulletinNo} đã ở trạng thái {b.Status}, không thể xóa xe.");

        var line = await db.TechnicalBulletinLines.FirstOrDefaultAsync(l => l.OrgId == Org && l.TechnicalBulletinId == b.Id && l.Vin == targetVin);
        if (line == null) return null;

        if (line.Status == "Completed")
            throw new InvalidOperationException($"Xe {targetVin} đã hoàn tất xử lý TSB, không thể xóa khỏi bản tin.");

        db.TechnicalBulletinLines.Remove(line);
        b.TotalVehicleCount = Math.Max(0, b.TotalVehicleCount - 1);
        await db.SaveChangesAsync();

        return await GetTechnicalBulletinAsync(code);
    }

    public async Task<object?> GetVehicleBulletinHistoryAsync(string vin)
    {
        var targetVin = vin.Trim().ToUpperInvariant();
        var v = await db.Vehicles.FirstOrDefaultAsync(x => x.OrgId == Org && x.Vin == targetVin);
        if (v == null) return null;

        var lines = await db.TechnicalBulletinLines
            .Where(l => l.OrgId == Org && l.Vin == targetVin)
            .OrderByDescending(l => l.Id)
            .ToListAsync();

        var bulletinIds = lines.Select(l => l.TechnicalBulletinId).Distinct().ToList();
        var bulletins = await db.TechnicalBulletins
            .Where(b => b.OrgId == Org && bulletinIds.Contains(b.Id))
            .ToDictionaryAsync(b => b.Id);

        return new
        {
            vin = v.Vin,
            model = v.Model,
            plateNo = v.PlateNo,
            dealerCode = v.DealerCode,
            lastBulletinNo = v.LastBulletinNo,
            lastBulletinDate = v.LastBulletinDate,
            totalBulletinsCount = lines.Count,
            completedBulletinsCount = lines.Count(l => l.Status == "Completed"),
            pendingBulletinsCount = lines.Count(l => l.Status != "Completed"),
            bulletins = lines.Select(l =>
            {
                bulletins.TryGetValue(l.TechnicalBulletinId, out var b);
                return new
                {
                    l.Id,
                    l.TechnicalBulletinId,
                    bulletinNo = l.BulletinNo,
                    title = b?.Title,
                    category = b?.Category,
                    severity = b?.Severity,
                    releaseDate = b?.ReleaseDate,
                    expiryDate = b?.ExpiryDate,
                    description = b?.Description,
                    remedy = b?.Remedy,
                    attachmentUrl = b?.AttachmentUrl,
                    bulletinStatus = b?.Status,
                    lineStatus = l.Status,
                    dealerCode = l.DealerCode,
                    technician = l.Technician,
                    odoKm = l.OdoKm,
                    roNo = l.RoNo,
                    resultNotes = l.ResultNotes,
                    inspectedAt = l.InspectedAt,
                    completedAt = l.CompletedAt,
                    remark = l.Remark
                };
            })
        };
    }

    public async Task<object> GetTechnicalBulletinSummaryAsync()
    {
        var bulletins = await db.TechnicalBulletins.Where(b => b.OrgId == Org).ToListAsync();
        var allLines = await db.TechnicalBulletinLines.Where(l => l.OrgId == Org).ToListAsync();

        var totalBulletins = bulletins.Count;
        var publishedCount = bulletins.Count(b => b.Status == "Published");
        var draftCount = bulletins.Count(b => b.Status == "Draft");
        var archivedCount = bulletins.Count(b => b.Status == "Archived");

        var totalVehicles = allLines.Count;
        var completedVehicles = allLines.Count(l => l.Status == "Completed");
        var pendingVehicles = allLines.Count(l => l.Status != "Completed");
        var overallCompletionPercent = totalVehicles > 0 ? Math.Round((decimal)completedVehicles / totalVehicles * 100, 1) : 0;

        var byCategory = bulletins.GroupBy(b => b.Category).Select(g => new
        {
            category = g.Key,
            count = g.Count(),
            published = g.Count(x => x.Status == "Published")
        }).ToList();

        var bySeverity = bulletins.GroupBy(b => b.Severity).Select(g => new
        {
            severity = g.Key,
            count = g.Count(),
            published = g.Count(x => x.Status == "Published")
        }).ToList();

        return new
        {
            totalBulletins,
            publishedBulletins = publishedCount,
            draftBulletins = draftCount,
            archivedBulletins = archivedCount,
            totalVehiclesAffected = totalVehicles,
            completedVehicles,
            pendingVehicles,
            overallCompletionPercent,
            byCategory,
            bySeverity
        };
    }

    // ===== Đề nghị & Lệnh giao dịch giải ngân ngân hàng mua xe ô tô cho Đại lý (BizHTC.VietinBank & BizHTC.MBBank / RQ_BankingTransactions / BankDisbursement) =====
    public async Task<object> CreateBankDisbursementAsync(CreateBankDisbursementDto dto)
    {
        if (string.IsNullOrWhiteSpace(dto.DealerCode) || string.IsNullOrWhiteSpace(dto.BankCode))
            throw new InvalidOperationException("Cần mã đại lý (DealerCode) và mã ngân hàng (BankCode) để lập hồ sơ đề nghị giải ngân.");

        var inputItems = new List<BankDisbursementItemInputDto>();
        if (dto.Items is { Count: > 0 })
        {
            inputItems.AddRange(dto.Items);
        }
        else if (dto.Vins is { Count: > 0 })
        {
            inputItems.AddRange(dto.Vins.Select(v => new BankDisbursementItemInputDto(v)));
        }

        if (inputItems.Count == 0)
            throw new InvalidOperationException("Cần ít nhất 1 dòng xe (Items hoặc Vins) trong hồ sơ đề nghị giải ngân.");

        var distinctItems = inputItems
            .Where(i => !string.IsNullOrWhiteSpace(i.Vin))
            .DistinctBy(i => i.Vin.Trim().ToUpperInvariant())
            .ToList();

        if (distinctItems.Count == 0)
            throw new InvalidOperationException("Danh sách số khung VIN không hợp lệ.");

        var vins = distinctItems.Select(i => i.Vin.Trim().ToUpperInvariant()).ToList();
        var vehicles = await db.Vehicles.Where(v => v.OrgId == Org && vins.Contains(v.Vin)).ToDictionaryAsync(v => v.Vin);

        if (vehicles.Count != vins.Count)
        {
            var missing = vins.Except(vehicles.Keys).ToList();
            throw new InvalidOperationException($"Không tìm thấy các số khung VIN sau trong hệ thống: {string.Join(", ", missing)}");
        }

        var transNo = string.IsNullOrWhiteSpace(dto.RQ_BankingTransNo)
            ? "BDIS" + DateTime.Now.ToString("yyMMddHHmmss")
            : dto.RQ_BankingTransNo.Trim().ToUpperInvariant();

        if (await db.BankDisbursements.AnyAsync(b => b.OrgId == Org && b.RQ_BankingTransNo == transNo))
            throw new InvalidOperationException($"Mã đề nghị giải ngân {transNo} đã tồn tại.");

        var bankCode = dto.BankCode.Trim().ToUpperInvariant();
        var bankName = !string.IsNullOrWhiteSpace(dto.BankName) ? dto.BankName.Trim() : bankCode switch
        {
            "VIETINBANK" or "CTG" => "Ngân hàng TMCP Công thương Việt Nam (VietinBank)",
            "MBBANK" or "MB" => "Ngân hàng TMCP Quân đội (MB Bank)",
            "VCB" => "Ngân hàng TMCP Ngoại thương Việt Nam (Vietcombank)",
            "VPB" => "Ngân hàng TMCP Việt Nam Thịnh Vượng (VPBank)",
            "TCB" => "Ngân hàng TMCP Kỹ thương Việt Nam (Techcombank)",
            "BIDV" => "Ngân hàng TMCP Đầu tư và Phát triển Việt Nam (BIDV)",
            _ => $"Ngân hàng {bankCode}"
        };

        var disRate = dto.DisbursementRate.HasValue && dto.DisbursementRate.Value > 0 ? dto.DisbursementRate.Value : 80;
        var disType = string.IsNullOrWhiteSpace(dto.DisbursementType) ? "AutoLoan" : dto.DisbursementType.Trim();

        var disbursement = new BankDisbursement
        {
            OrgId = Org,
            RQ_BankingTransNo = transNo,
            RQ_BankingTransNoUser = dto.RQ_BankingTransNoUser?.Trim(),
            DealerCode = dto.DealerCode.Trim().ToUpperInvariant(),
            BankCode = bankCode,
            BankName = bankName,
            BizResNumber = dto.BizResNumber?.Trim(),
            BeneficiaryAccountNo = dto.BeneficiaryAccountNo?.Trim() ?? "110002899999 - VietinBank SGD 1",
            BeneficiaryAccountName = dto.BeneficiaryAccountName?.Trim() ?? "Công ty Cổ phần Liên doanh Ô tô Hyundai Thành Công Việt Nam",
            BeneficiaryBankCode = dto.BeneficiaryBankCode?.Trim() ?? "VIETINBANK",
            DisbursementType = disType,
            DisbursementRate = disRate,
            FilePath = dto.FilePath?.Trim(),
            BkTransStatus = "Draft",
            BkTransBankStatus = "Pending",
            Remark = dto.Remark?.Trim(),
            CreatedBy = dto.CreatedBy?.Trim(),
            CreatedAt = DateTime.Now
        };

        db.BankDisbursements.Add(disbursement);
        await db.SaveChangesAsync();

        decimal totalCollateral = 0;
        decimal totalDisbursement = 0;

        foreach (var item in distinctItems)
        {
            var lineVin = item.Vin.Trim().ToUpperInvariant();
            var v = vehicles[lineVin];

            var unitPrice = item.UnitPrice.HasValue && item.UnitPrice.Value > 0
                ? item.UnitPrice.Value
                : GetDefaultCarPrice(v.Model);

            var collateralVal = item.CollateralValue.HasValue && item.CollateralValue.Value > 0
                ? item.CollateralValue.Value
                : unitPrice;

            var percent = item.DisbursementPercent.HasValue && item.DisbursementPercent.Value > 0
                ? item.DisbursementPercent.Value
                : disRate;

            var disAmt = item.DisbursementAmount.HasValue && item.DisbursementAmount.Value > 0
                ? item.DisbursementAmount.Value
                : Math.Round(collateralVal * percent / 100, 0);

            totalCollateral += collateralVal;
            totalDisbursement += disAmt;

            var line = new BankDisbursementLine
            {
                OrgId = Org,
                BankDisbursementId = disbursement.Id,
                RQ_BankingTransNo = transNo,
                Vin = lineVin,
                Model = v.Model,
                EngineNo = v.EngineNo,
                Color = v.Color,
                InvoiceNo = item.InvoiceNo?.Trim() ?? v.InvoiceNo,
                InvoiceDate = item.InvoiceDate ?? v.InvoiceDate,
                GuaranteeNo = item.GuaranteeNo?.Trim(),
                UnitPrice = unitPrice,
                CollateralValue = collateralVal,
                DisbursementPercent = percent,
                DisbursementAmount = disAmt,
                DisbursedAmount = 0,
                Status = "Pending",
                Remark = item.Remark?.Trim()
            };

            db.BankDisbursementLines.Add(line);

            Log(lineVin, "BankDisbursementDraftCreated",
                $"{transNo} Lập hồ sơ đề nghị giải ngân NH {bankCode} cho đại lý {disbursement.DealerCode}. Định giá xe: {collateralVal:N0} VNĐ, Số tiền xin giải ngân ({percent}%): {disAmt:N0} VNĐ");
        }

        disbursement.TotalVehicleCount = distinctItems.Count;
        disbursement.TotalCollateralValue = totalCollateral;
        disbursement.TotalDisbursementAmount = totalDisbursement;

        await db.SaveChangesAsync();

        return new
        {
            disbursement.RQ_BankingTransNo,
            disbursement.RQ_BankingTransNoUser,
            disbursement.DealerCode,
            disbursement.BankCode,
            disbursement.BankName,
            disbursement.DisbursementType,
            disbursement.TotalVehicleCount,
            disbursement.TotalCollateralValue,
            disbursement.TotalDisbursementAmount,
            disbursement.BkTransStatus,
            disbursement.BkTransBankStatus,
            disbursement.CreatedAt,
            vins = distinctItems.Select(i => i.Vin)
        };
    }

    public async Task<object> ListBankDisbursementsAsync(string? status, string? bank, string? dealer, string? transNo, string? vin)
    {
        var q = db.BankDisbursements.Where(b => b.OrgId == Org);
        if (!string.IsNullOrWhiteSpace(status)) q = q.Where(b => b.BkTransStatus == status);
        if (!string.IsNullOrWhiteSpace(bank)) { var bCode = bank.Trim().ToUpperInvariant(); q = q.Where(b => b.BankCode == bCode); }
        if (!string.IsNullOrWhiteSpace(dealer)) { var dCode = dealer.Trim().ToUpperInvariant(); q = q.Where(b => b.DealerCode.Contains(dCode)); }
        if (!string.IsNullOrWhiteSpace(transNo)) { var tCode = transNo.Trim().ToUpperInvariant(); q = q.Where(b => b.RQ_BankingTransNo.Contains(tCode)); }
        if (!string.IsNullOrWhiteSpace(vin))
        {
            var vv = vin.Trim().ToUpperInvariant();
            var matchedNos = await db.BankDisbursementLines.Where(l => l.OrgId == Org && l.Vin == vv).Select(l => l.RQ_BankingTransNo).Distinct().ToListAsync();
            q = q.Where(b => matchedNos.Contains(b.RQ_BankingTransNo));
        }

        var items = await q.OrderByDescending(b => b.Id).Take(500).Select(b => new
        {
            b.Id,
            b.RQ_BankingTransNo,
            b.RQ_BankingTransNoUser,
            b.DealerCode,
            b.BankCode,
            b.BankName,
            b.BizResNumber,
            b.BeneficiaryAccountNo,
            b.BeneficiaryAccountName,
            b.BeneficiaryBankCode,
            b.DisbursementType,
            b.TotalVehicleCount,
            b.TotalCollateralValue,
            b.DisbursementRate,
            b.TotalDisbursementAmount,
            b.DisbursedAmount,
            b.BkTransStatus,
            b.BkTransBankStatus,
            b.RefBankCode,
            b.DisbursementDate,
            b.BankRemark,
            b.FilePath,
            b.Remark,
            b.CreatedBy,
            b.CreatedAt,
            b.ApprovedBy,
            b.ApprovedAt,
            b.PushedBy,
            b.PushedAt,
            b.DisbursedBy,
            b.DisbursedAt,
            b.RejectedBy,
            b.RejectedAt,
            b.RejectReason,
            b.CancelledBy,
            b.CancelledAt,
            b.CancelReason,
            lineCount = db.BankDisbursementLines.Count(l => l.OrgId == Org && l.BankDisbursementId == b.Id)
        }).ToListAsync();

        return new { count = items.Count, items };
    }

