            b.BkTransStatus,
            b.BkTransBankStatus,
            b.RefBankCode,
            b.DisbursementDate,
            b.BankRemark,
            b.FilePath,
            b.Remark,
            b.CreatedBy,
            b.CreatedAt,
            b.ApprovedBy,
            b.ApprovedAt,
            b.PushedBy,
            b.PushedAt,
            b.DisbursedBy,
            b.DisbursedAt,
            b.RejectedBy,
            b.RejectedAt,
            b.RejectReason,
            b.CancelledBy,
            b.CancelledAt,
            b.CancelReason,
