        var lines = await db.PdiPaymentLines.Where(l => l.OrgId == Org && l.PdiPaymentId == payment.Id).OrderBy(l => l.LineIndex).ToListAsync();
        var lineVins = lines.Select(l => l.Vin).ToList();
