            l.LineIndex,
            l.Vin,
            l.Model,
            l.SpecCode,
            l.EngineNo,
            l.Color,
            l.StorageCode,
            l.DealerCode,
            l.PdiReqNo,
            l.DlvMnNo,
            l.CostInCheck,
            l.CostOutCheck,
            l.TotalCostCheck,
            l.PdiCompletedDate,
            l.PdiResult,
