                v.Model,
                v.Color,
                v.EngineNo,
                status = v.Status.ToString(),
                v.DealerCode,
                v.StorageCode,
                v.IsPdiPaid,
                v.PdiPaidAmount,
                v.LastPdiPaymentNo,
                v.LastPdiPaymentDate
            } : null
        }).ToList();

        return new
        {
            payment.Id,
            payment.PmtPdiNo,
            payment.PmtPdiNoUser,
            payment.DealerCode,
            payment.DealerName,
            payment.StorageCode,
            payment.PeriodMonth,
            payment.PaymentDate,
            payment.TotalVehicleCount,
            payment.TotalCostIn,
            payment.TotalCostOut,
            payment.TotalAmount,
            payment.VatRate,
            payment.VatAmount,
            payment.TotalAmountAfterVAT,
            payment.FileSigned,
            payment.BankRefNo,
            payment.SettledDate,
            payment.Status,
            payment.CreatedBy,
            payment.CreatedAt,
            payment.Approved1By,
            payment.Approved1At,
            payment.Approved2By,
            payment.Approved2At,
            payment.TCMSSignedBy,
            payment.TCMSSignedAt,
            payment.HTVSignedBy,
            payment.HTVSignedAt,
            payment.SettledBy,
            payment.SettledAt,
            payment.RejectedBy,
            payment.RejectedAt,
            payment.RejectReason,
            payment.CancelledBy,
            payment.CancelledAt,
            payment.CancelReason,
            payment.Remark,
            lines = details
        };
    }

    public async Task<object?> UpdatePdiPaymentHeaderAsync(string pmtPdiNo, UpdatePdiPaymentHeaderDto dto)
    {
        pmtPdiNo = pmtPdiNo.Trim().ToUpperInvariant();
        var payment = await db.PdiPayments.FirstOrDefaultAsync(p => p.OrgId == Org && p.PmtPdiNo == pmtPdiNo);
        if (payment is null) return null;

        if (payment.Status is "HTVSigned" or "Settled" or "Cancelled" or "Rejected")
            throw new InvalidOperationException($"Không thể sửa bảng kê quyết toán PDI ở trạng thái {payment.Status}.");

        if (dto.PmtPdiNoUser != null) payment.PmtPdiNoUser = dto.PmtPdiNoUser.Trim();
        if (!string.IsNullOrWhiteSpace(dto.DealerCode)) payment.DealerCode = dto.DealerCode.Trim().ToUpperInvariant();
        if (dto.DealerName != null) payment.DealerName = dto.DealerName.Trim();
        if (dto.StorageCode != null) payment.StorageCode = dto.StorageCode.Trim();
        if (!string.IsNullOrWhiteSpace(dto.PeriodMonth)) payment.PeriodMonth = dto.PeriodMonth.Trim();
        if (dto.PaymentDate.HasValue) payment.PaymentDate = dto.PaymentDate.Value;
        if (!string.IsNullOrWhiteSpace(dto.BankRefNo)) payment.BankRefNo = dto.BankRefNo.Trim();
        if (dto.SettledDate.HasValue) payment.SettledDate = dto.SettledDate.Value;
        if (!string.IsNullOrWhiteSpace(dto.FileSigned)) payment.FileSigned = dto.FileSigned.Trim();
        if (dto.Remark != null) payment.Remark = dto.Remark.Trim();

        if (dto.VatRate.HasValue && dto.VatRate.Value >= 0)
        {
            payment.VatRate = dto.VatRate.Value;
            payment.VatAmount = Math.Round(payment.TotalAmount * payment.VatRate / 100, 0);
            payment.TotalAmountAfterVAT = payment.TotalAmount + payment.VatAmount;
        }

        await db.SaveChangesAsync();

        return new
        {
            payment.PmtPdiNo,
            payment.PmtPdiNoUser,
            payment.DealerCode,
            payment.DealerName,
            payment.PeriodMonth,
            payment.PaymentDate,
            payment.TotalAmount,
            payment.VatRate,
            payment.VatAmount,
            payment.TotalAmountAfterVAT,
            payment.BankRefNo,
            payment.SettledDate,
            payment.Status,
            payment.Remark
        };
    }

    public async Task<object?> PdiPaymentTransitionAsync(string pmtPdiNo, string action, PdiPaymentTransitionDto? dto)
    {
        pmtPdiNo = pmtPdiNo.Trim().ToUpperInvariant();
        var act = action.Trim().ToLowerInvariant();

        var payment = await db.PdiPayments.FirstOrDefaultAsync(p => p.OrgId == Org && p.PmtPdiNo == pmtPdiNo);
        if (payment is null) return null;

        var lines = await db.PdiPaymentLines.Where(l => l.OrgId == Org && l.PdiPaymentId == payment.Id).ToListAsync();
        var lineVins = lines.Select(l => l.Vin).ToList();
        var vehicles = await db.Vehicles.Where(v => v.OrgId == Org && lineVins.Contains(v.Vin)).ToDictionaryAsync(v => v.Vin);

        var now = DateTime.Now;

        switch (act)
        {
            case "submit":
                if (payment.Status != "Draft") return null;
                payment.Status = "Submitted";
                if (!string.IsNullOrWhiteSpace(dto?.Note))
                    payment.Remark = (payment.Remark + " | Trình duyệt: " + dto.Note).Trim(' ', '|');

                foreach (var line in lines)
                {
                    line.Status = "Submitted";
                    Log(line.Vin, "PdiPaymentSubmitted", $"{pmtPdiNo} Trình duyệt bảng kê quyết toán PDI kỳ {payment.PeriodMonth} tới Hãng OEM. Số tiền: {line.TotalCostCheck:N0} VNĐ");
                }
                break;

            case "approve1":
            case "approve-tech":
            case "tech-approve":
                if (payment.Status is not ("Draft" or "Submitted")) return null;
                payment.Status = "Approved1";
                payment.Approved1By = dto?.Actor?.Trim() ?? "OEM.ServiceDepartment";
                payment.Approved1At = now;
                if (!string.IsNullOrWhiteSpace(dto?.Note))
                    payment.Remark = (payment.Remark + " | Duyệt kỹ thuật: " + dto.Note).Trim(' ', '|');

                foreach (var line in lines)
                {
                    line.Status = "Approved1";
                    Log(line.Vin, "PdiPaymentApproved1", $"{pmtPdiNo} Bộ phận Dịch vụ & Sau bán hàng OEM thẩm định đạt chuẩn chất lượng PDI. Người duyệt: {payment.Approved1By}");
                }
                break;

            case "approve2":
            case "approve-finance":
            case "finance-approve":
            case "approve":
                if (payment.Status is not ("Submitted" or "Approved1")) return null;
                payment.Status = "Approved2";
                payment.Approved2By = dto?.Actor?.Trim() ?? "OEM.FinanceDepartment";
                payment.Approved2At = now;
                if (string.IsNullOrWhiteSpace(payment.Approved1By))
                {
                    payment.Approved1By = payment.Approved2By;
                    payment.Approved1At = now;
                }
                if (!string.IsNullOrWhiteSpace(dto?.Note))
                    payment.Remark = (payment.Remark + " | Duyệt tài chính: " + dto.Note).Trim(' ', '|');

                foreach (var line in lines)
                {
                    line.Status = "Approved2";
                    Log(line.Vin, "PdiPaymentApproved2", $"{pmtPdiNo} Bộ phận Tài chính Kế toán OEM phê duyệt định mức quyết toán PDI. Người duyệt: {payment.Approved2By}");
                }
                break;

            case "tcms-sign":
            case "tcmssign":
            case "sign-tcms":
                if (payment.Status is not ("Approved1" or "Approved2")) return null;
                payment.Status = "TCMSSigned";
                payment.TCMSSignedBy = dto?.Actor?.Trim() ?? "OEM.TCMSDirector";
                payment.TCMSSignedAt = now;
                if (!string.IsNullOrWhiteSpace(dto?.FileSigned)) payment.FileSigned = dto.FileSigned.Trim();
                if (!string.IsNullOrWhiteSpace(dto?.Note))
                    payment.Remark = (payment.Remark + " | Ký số TCMS: " + dto.Note).Trim(' ', '|');

                foreach (var line in lines)
                {
                    line.Status = "TCMSSigned";
                    Log(line.Vin, "PdiPaymentTCMSSigned", $"{pmtPdiNo} Lãnh đạo Khối Phân phối TCMS ký số phê duyệt chi trả PDI. Người ký: {payment.TCMSSignedBy}");
                }
                break;

            case "htv-sign":
            case "htvsign":
            case "sign-htv":
            case "settle":
            case "complete":
            case "finish":
                if (payment.Status is not ("Approved2" or "TCMSSigned" or "Approved1")) return null;
                payment.Status = "Settled";
                payment.HTVSignedBy = dto?.Actor?.Trim() ?? "HTV.GeneralDirector";
                payment.HTVSignedAt = now;
                payment.SettledBy = dto?.Actor?.Trim() ?? "HTV.ChiefAccountant";
                payment.SettledAt = now;
                payment.SettledDate = dto?.TransitionDate ?? now;
                if (!string.IsNullOrWhiteSpace(dto?.BankRefNo)) payment.BankRefNo = dto.BankRefNo.Trim();
                if (!string.IsNullOrWhiteSpace(dto?.FileSigned)) payment.FileSigned = dto.FileSigned.Trim();
                if (string.IsNullOrWhiteSpace(payment.TCMSSignedBy))
                {
                    payment.TCMSSignedBy = payment.HTVSignedBy;
                    payment.TCMSSignedAt = now;
                }
                if (!string.IsNullOrWhiteSpace(dto?.Note))
                    payment.Remark = (payment.Remark + " | Thanh toán hoàn tất: " + dto.Note).Trim(' ', '|');

                foreach (var line in lines)
                {
                    line.Status = "Settled";
                    if (vehicles.TryGetValue(line.Vin, out var v))
                    {
                        v.IsPdiPaid = true;
                        v.PdiPaidAmount += line.TotalCostCheck;
                        v.LastPdiPaymentNo = payment.PmtPdiNo;
                        v.LastPdiPaymentDate = now;
                        v.PdiPaymentCount++;
                        Log(v.Vin, "PdiPaymentSettled", $"{pmtPdiNo} Hoàn tất thanh toán/bù trừ công nợ chi phí PDI cho đại lý {payment.DealerCode}. Số tiền: {line.TotalCostCheck:N0} VNĐ. Mã GD: {payment.BankRefNo ?? "N/A"}");
                    }
                }
                break;

            case "reject":
                if (payment.Status is "Settled" or "Cancelled") return null;
                payment.Status = "Rejected";
                payment.RejectedBy = dto?.Actor?.Trim() ?? "OEM.Approver";
                payment.RejectedAt = now;
                payment.RejectReason = dto?.Reason?.Trim() ?? dto?.Note?.Trim();
                if (!string.IsNullOrWhiteSpace(dto?.Note))
                    payment.Remark = (payment.Remark + " | Từ chối: " + dto.Note).Trim(' ', '|');

                foreach (var line in lines)
                {
                    line.Status = "Rejected";
                    Log(line.Vin, "PdiPaymentRejected", $"{pmtPdiNo} Từ chối bảng kê quyết toán PDI: {payment.RejectReason ?? "N/A"}");
                }
                break;

            case "cancel":
                if (payment.Status is "Settled") return null;
                payment.Status = "Cancelled";
                payment.CancelledBy = dto?.Actor?.Trim() ?? "PdiCoordinator";
                payment.CancelledAt = now;
                payment.CancelReason = dto?.Reason?.Trim() ?? dto?.Note?.Trim();
                if (!string.IsNullOrWhiteSpace(dto?.Note))
                    payment.Remark = (payment.Remark + " | Hủy bảng kê: " + dto.Note).Trim(' ', '|');

                foreach (var line in lines)
                {
                    line.Status = "Cancelled";
                    Log(line.Vin, "PdiPaymentCancelled", $"{pmtPdiNo} Hủy bảng kê quyết toán PDI: {payment.CancelReason ?? "N/A"}");
                }
                break;

            default:
                return null;
        }

        await db.SaveChangesAsync();

        return new
        {
            payment.PmtPdiNo,
            payment.DealerCode,
            payment.PeriodMonth,
            status = payment.Status,
            payment.TotalVehicleCount,
            payment.TotalAmount,
            payment.TotalAmountAfterVAT,
            payment.Approved1At,
            payment.Approved2At,
            payment.TCMSSignedAt,
            payment.HTVSignedAt,
            payment.SettledAt,
            payment.BankRefNo,
            payment.SettledDate
        };
    }

    public async Task<object?> AddPdiPaymentLinesAsync(string pmtPdiNo, List<PdiPaymentItemInputDto> items)
    {
        pmtPdiNo = pmtPdiNo.Trim().ToUpperInvariant();
        var payment = await db.PdiPayments.FirstOrDefaultAsync(p => p.OrgId == Org && p.PmtPdiNo == pmtPdiNo);
        if (payment is null) return null;

        if (payment.Status is "HTVSigned" or "Settled" or "Cancelled" or "Rejected")
            throw new InvalidOperationException($"Không thể thêm xe vào bảng kê quyết toán PDI ở trạng thái {payment.Status}.");

        var existingLines = await db.PdiPaymentLines.Where(l => l.OrgId == Org && l.PdiPaymentId == payment.Id).ToListAsync();
        var existingVins = new HashSet<string>(existingLines.Select(l => l.Vin), StringComparer.OrdinalIgnoreCase);

        var newVins = items.Where(i => !string.IsNullOrWhiteSpace(i.Vin))
                           .Select(i => i.Vin.Trim().ToUpperInvariant())
                           .Where(v => !existingVins.Contains(v))
                           .Distinct().ToList();

        if (newVins.Count == 0)
            throw new InvalidOperationException("Không có số khung VIN mới hợp lệ để thêm vào bảng kê.");

        var vehicles = await db.Vehicles.Where(v => v.OrgId == Org && newVins.Contains(v.Vin)).ToDictionaryAsync(v => v.Vin);
        foreach (var vin in newVins)
        {
            if (!vehicles.ContainsKey(vin))
                throw new InvalidOperationException($"Không tìm thấy số khung VIN {vin} trong hệ thống.");
        }

        int maxIndex = existingLines.Count > 0 ? existingLines.Max(l => l.LineIndex) : 0;

        foreach (var it in items)
        {
            var cleanVin = it.Vin.Trim().ToUpperInvariant();
            if (!newVins.Contains(cleanVin)) continue;

            var v = vehicles[cleanVin];
            var model = !string.IsNullOrWhiteSpace(it.Model) ? it.Model.Trim() : v.Model;
            var spec = it.SpecCode ?? v.ModelYear?.ToString();
            var engine = it.EngineNo ?? v.EngineNo;
            var color = it.Color ?? v.Color;
            var storage = it.StorageCode ?? v.StorageCode ?? payment.StorageCode;
            var lineDealer = it.DealerCode ?? v.DealerCode ?? payment.DealerCode;

            var costIn = it.CostInCheck.HasValue && it.CostInCheck.Value >= 0 ? it.CostInCheck.Value : 250000m;
            var costOut = it.CostOutCheck.HasValue && it.CostOutCheck.Value >= 0 ? it.CostOutCheck.Value : 200000m;
            var totalLineCost = costIn + costOut;

            var line = new PdiPaymentLine
            {
                OrgId = Org,
                PdiPaymentId = payment.Id,
                PmtPdiNo = pmtPdiNo,
                LineIndex = ++maxIndex,
                Vin = cleanVin,
                Model = model,
                SpecCode = spec,
                EngineNo = engine,
                Color = color,
                StorageCode = storage,
                DealerCode = lineDealer,
                PdiReqNo = it.PdiReqNo?.Trim(),
                DlvMnNo = it.DlvMnNo?.Trim(),
                CostInCheck = costIn,
                CostOutCheck = costOut,
                TotalCostCheck = totalLineCost,
                PdiCompletedDate = it.PdiCompletedDate ?? DateTime.Now,
                PdiResult = string.IsNullOrWhiteSpace(it.PdiResult) ? "Passed" : it.PdiResult.Trim(),
                Status = "Pending",
                Remark = it.Remark?.Trim()
            };

            db.PdiPaymentLines.Add(line);
            Log(cleanVin, "PdiPaymentLineAdded", $"{pmtPdiNo} Bổ sung xe vào bảng kê quyết toán PDI kỳ {payment.PeriodMonth}. Số tiền: {totalLineCost:N0} VNĐ");
        }

        await db.SaveChangesAsync();

        var allLines = await db.PdiPaymentLines.Where(l => l.OrgId == Org && l.PdiPaymentId == payment.Id).ToListAsync();
        payment.TotalVehicleCount = allLines.Count;
        payment.TotalCostIn = allLines.Sum(l => l.CostInCheck);
        payment.TotalCostOut = allLines.Sum(l => l.CostOutCheck);
        payment.TotalAmount = payment.TotalCostIn + payment.TotalCostOut;
        payment.VatAmount = Math.Round(payment.TotalAmount * payment.VatRate / 100, 0);
        payment.TotalAmountAfterVAT = payment.TotalAmount + payment.VatAmount;

        await db.SaveChangesAsync();

        return new
        {
            payment.PmtPdiNo,
            addedCount = newVins.Count,
            payment.TotalVehicleCount,
            payment.TotalCostIn,
            payment.TotalCostOut,
            payment.TotalAmount,
            payment.TotalAmountAfterVAT
        };
    }

    public async Task<object?> UpdatePdiPaymentLineAsync(string pmtPdiNo, string vin, UpdatePdiPaymentLineDto dto)
    {
        pmtPdiNo = pmtPdiNo.Trim().ToUpperInvariant();
        vin = vin.Trim().ToUpperInvariant();

        var payment = await db.PdiPayments.FirstOrDefaultAsync(p => p.OrgId == Org && p.PmtPdiNo == pmtPdiNo);
        if (payment is null) return null;

        if (payment.Status is "HTVSigned" or "Settled" or "Cancelled" or "Rejected")
            throw new InvalidOperationException($"Không thể sửa dòng chi tiết bảng kê quyết toán PDI ở trạng thái {payment.Status}.");

        var line = await db.PdiPaymentLines.FirstOrDefaultAsync(l => l.OrgId == Org && l.PdiPaymentId == payment.Id && l.Vin == vin);
        if (line is null) return null;

        if (!string.IsNullOrWhiteSpace(dto.Model)) line.Model = dto.Model.Trim();
        if (dto.SpecCode != null) line.SpecCode = dto.SpecCode.Trim();
        if (dto.EngineNo != null) line.EngineNo = dto.EngineNo.Trim();
        if (dto.Color != null) line.Color = dto.Color.Trim();
        if (dto.StorageCode != null) line.StorageCode = dto.StorageCode.Trim();
        if (dto.DealerCode != null) line.DealerCode = dto.DealerCode.Trim();
        if (dto.PdiReqNo != null) line.PdiReqNo = dto.PdiReqNo.Trim();
        if (dto.DlvMnNo != null) line.DlvMnNo = dto.DlvMnNo.Trim();
        if (dto.PdiCompletedDate.HasValue) line.PdiCompletedDate = dto.PdiCompletedDate.Value;
        if (!string.IsNullOrWhiteSpace(dto.PdiResult)) line.PdiResult = dto.PdiResult.Trim();
        if (!string.IsNullOrWhiteSpace(dto.Status)) line.Status = dto.Status.Trim();
        if (dto.Remark != null) line.Remark = dto.Remark.Trim();

        if (dto.CostInCheck.HasValue && dto.CostInCheck.Value >= 0) line.CostInCheck = dto.CostInCheck.Value;
        if (dto.CostOutCheck.HasValue && dto.CostOutCheck.Value >= 0) line.CostOutCheck = dto.CostOutCheck.Value;
        line.TotalCostCheck = line.CostInCheck + line.CostOutCheck;

        await db.SaveChangesAsync();

        var allLines = await db.PdiPaymentLines.Where(l => l.OrgId == Org && l.PdiPaymentId == payment.Id).ToListAsync();
        payment.TotalCostIn = allLines.Sum(l => l.CostInCheck);
        payment.TotalCostOut = allLines.Sum(l => l.CostOutCheck);
        payment.TotalAmount = payment.TotalCostIn + payment.TotalCostOut;
        payment.VatAmount = Math.Round(payment.TotalAmount * payment.VatRate / 100, 0);
        payment.TotalAmountAfterVAT = payment.TotalAmount + payment.VatAmount;

        await db.SaveChangesAsync();

        return new
        {
            line.PmtPdiNo,
            line.Vin,
            line.Model,
            line.CostInCheck,
            line.CostOutCheck,
            line.TotalCostCheck,
            line.PdiResult,
            line.Status,
            paymentTotalAmount = payment.TotalAmount,
            paymentTotalAmountAfterVAT = payment.TotalAmountAfterVAT
        };
    }

    public async Task<object?> RemovePdiPaymentLineAsync(string pmtPdiNo, string vin)
    {
        pmtPdiNo = pmtPdiNo.Trim().ToUpperInvariant();
        vin = vin.Trim().ToUpperInvariant();

        var payment = await db.PdiPayments.FirstOrDefaultAsync(p => p.OrgId == Org && p.PmtPdiNo == pmtPdiNo);
        if (payment is null) return null;

        if (payment.Status is "HTVSigned" or "Settled" or "Cancelled" or "Rejected")
            throw new InvalidOperationException($"Không thể xóa dòng xe khỏi bảng kê quyết toán PDI ở trạng thái {payment.Status}.");

        var line = await db.PdiPaymentLines.FirstOrDefaultAsync(l => l.OrgId == Org && l.PdiPaymentId == payment.Id && l.Vin == vin);
        if (line is null) return null;

        db.PdiPaymentLines.Remove(line);
        Log(vin, "PdiPaymentLineRemoved", $"{pmtPdiNo} Rút xe khỏi bảng kê quyết toán PDI kỳ {payment.PeriodMonth}");
        await db.SaveChangesAsync();

        var allLines = await db.PdiPaymentLines.Where(l => l.OrgId == Org && l.PdiPaymentId == payment.Id).ToListAsync();
        payment.TotalVehicleCount = allLines.Count;
        payment.TotalCostIn = allLines.Sum(l => l.CostInCheck);
        payment.TotalCostOut = allLines.Sum(l => l.CostOutCheck);
        payment.TotalAmount = payment.TotalCostIn + payment.TotalCostOut;
        payment.VatAmount = Math.Round(payment.TotalAmount * payment.VatRate / 100, 0);
        payment.TotalAmountAfterVAT = payment.TotalAmount + payment.VatAmount;

        await db.SaveChangesAsync();

        return new
        {
            payment.PmtPdiNo,
            removedVin = vin,
            payment.TotalVehicleCount,
            payment.TotalCostIn,
            payment.TotalCostOut,
            payment.TotalAmount,
            payment.TotalAmountAfterVAT
        };
    }

    public async Task<object?> GetVehiclePdiPaymentInfoAsync(string vin)
    {
        vin = vin.Trim().ToUpperInvariant();
        var vehicle = await db.Vehicles.FirstOrDefaultAsync(v => v.OrgId == Org && v.Vin == vin);
        if (vehicle is null) return null;

        var lastLine = await db.PdiPaymentLines.Where(l => l.OrgId == Org && l.Vin == vin).OrderByDescending(l => l.Id).FirstOrDefaultAsync();
        PdiPayment? lastPayment = null;
        if (lastLine != null)
        {
            lastPayment = await db.PdiPayments.FirstOrDefaultAsync(p => p.OrgId == Org && p.Id == lastLine.PdiPaymentId);
        }

        return new
        {
            vehicle.Vin,
            vehicle.Model,
            vehicle.EngineNo,
            vehicle.Color,
            vehicle.ModelYear,
            vehicle.IsPdiPaid,
            vehicle.PdiPaidAmount,
            vehicle.LastPdiPaymentNo,
            vehicle.LastPdiPaymentDate,
            vehicle.PdiPaymentCount,
            pdiPayment = lastPayment == null ? null : new
            {
                lastPayment.PmtPdiNo,
                lastPayment.DealerCode,
                lastPayment.PeriodMonth,
                lastPayment.PaymentDate,
                lastPayment.Status,
                lastPayment.BankRefNo,
                lastPayment.SettledDate
            },
            pdiPaymentLine = lastLine == null ? null : new
            {
                lastLine.CostInCheck,
                lastLine.CostOutCheck,
                lastLine.TotalCostCheck,
                lastLine.PdiCompletedDate,
                lastLine.PdiResult,
                lastLine.Status,
                lastLine.Remark
            }
        };
    }

    public async Task<object?> GetVehiclePdiPaymentHistoryAsync(string vin)
    {
        vin = vin.Trim().ToUpperInvariant();
        var vehicle = await db.Vehicles.FirstOrDefaultAsync(v => v.OrgId == Org && v.Vin == vin);
        if (vehicle is null) return null;

        var events = await db.Events
            .Where(e => e.OrgId == Org && e.Vin == vin && (e.Kind.StartsWith("PdiPayment") || e.Kind.StartsWith("Pdi")))
            .OrderByDescending(e => e.At)
            .ToListAsync();

        var paymentLines = await db.PdiPaymentLines
            .Where(l => l.OrgId == Org && l.Vin == vin)
            .OrderByDescending(l => l.Id)
            .ToListAsync();

        var paymentIds = paymentLines.Select(l => l.PdiPaymentId).Distinct().ToList();
        var payments = await db.PdiPayments.Where(p => p.OrgId == Org && paymentIds.Contains(p.Id)).ToDictionaryAsync(p => p.Id);

        var historyLines = paymentLines.Select(l => new
        {
            l.PmtPdiNo,
            l.Model,
            l.CostInCheck,
            l.CostOutCheck,
            l.TotalCostCheck,
            l.PdiCompletedDate,
            l.PdiResult,
            l.Status,
            l.Remark,
            payment = payments.TryGetValue(l.PdiPaymentId, out var p) ? new
            {
                p.DealerCode,
                p.PeriodMonth,
                p.PaymentDate,
                p.Status,
                p.BankRefNo,
                p.SettledDate
            } : null
        }).ToList();

        return new
        {
            vehicle.Vin,
            vehicle.Model,
            vehicle.IsPdiPaid,
            vehicle.PdiPaidAmount,
            vehicle.LastPdiPaymentNo,
            vehicle.LastPdiPaymentDate,
            vehicle.PdiPaymentCount,
            history = events.Select(e => new { e.Id, e.Kind, e.Note, e.At }),
            pdiPaymentLines = historyLines
        };
    }

    public async Task<object> GetPdiPaymentSummaryAsync(string? dealerCode, string? periodMonth, string? storageCode)
    {
        var q = db.PdiPayments.Where(p => p.OrgId == Org);
        if (!string.IsNullOrWhiteSpace(dealerCode)) q = q.Where(p => p.DealerCode.ToLower() == dealerCode.Trim().ToLower());
        if (!string.IsNullOrWhiteSpace(periodMonth)) q = q.Where(p => p.PeriodMonth == periodMonth.Trim());
        if (!string.IsNullOrWhiteSpace(storageCode)) q = q.Where(p => p.StorageCode != null && p.StorageCode.ToLower() == storageCode.Trim().ToLower());

        var payments = await q.ToListAsync();
        var paymentIds = payments.Select(x => x.Id).ToList();
        var lines = await db.PdiPaymentLines.Where(l => l.OrgId == Org && paymentIds.Contains(l.PdiPaymentId)).ToListAsync();

        int totalPayments = payments.Count;
        int totalDraft = payments.Count(x => x.Status == "Draft");
        int totalSubmitted = payments.Count(x => x.Status == "Submitted");
        int totalApproved1 = payments.Count(x => x.Status == "Approved1");
        int totalApproved2 = payments.Count(x => x.Status == "Approved2");
        int totalTCMSSigned = payments.Count(x => x.Status == "TCMSSigned");
        int totalSettled = payments.Count(x => x.Status is "HTVSigned" or "Settled");
        int totalCancelled = payments.Count(x => x.Status is "Cancelled" or "Rejected");

        int totalVehicleCount = lines.Where(l => l.Status != "Cancelled").Count();
        decimal totalCostIn = lines.Where(l => l.Status != "Cancelled").Sum(l => l.CostInCheck);
        decimal totalCostOut = lines.Where(l => l.Status != "Cancelled").Sum(l => l.CostOutCheck);
        decimal totalAmount = totalCostIn + totalCostOut;
        decimal totalVatAmount = payments.Where(p => p.Status != "Cancelled" && p.Status != "Rejected").Sum(p => p.VatAmount);
        decimal totalAmountAfterVAT = payments.Where(p => p.Status != "Cancelled" && p.Status != "Rejected").Sum(p => p.TotalAmountAfterVAT);

        decimal settlementRatePercent = totalPayments > 0 ? Math.Round((decimal)totalSettled / totalPayments * 100, 1) : 0;

        var byDealer = payments.GroupBy(p => p.DealerCode).Select(g =>
        {
            var pIds = g.Select(x => x.Id).ToList();
            var dLines = lines.Where(l => pIds.Contains(l.PdiPaymentId) && l.Status != "Cancelled").ToList();
            var settledAmount = g.Where(x => x.Status is "HTVSigned" or "Settled").Sum(x => x.TotalAmountAfterVAT);
            return new
            {
                dealerCode = g.Key,
                dealerName = g.First().DealerName ?? g.Key,
                paymentCount = g.Count(),
                totalVehicles = dLines.Count,
                totalAmount = g.Sum(x => x.TotalAmountAfterVAT),
                settledAmount
            };
        }).OrderByDescending(x => x.totalAmount).ToList();

        var byStorage = payments.Where(p => !string.IsNullOrWhiteSpace(p.StorageCode)).GroupBy(p => p.StorageCode!).Select(g =>
        {
            var pIds = g.Select(x => x.Id).ToList();
            var sLines = lines.Where(l => pIds.Contains(l.PdiPaymentId) && l.Status != "Cancelled").ToList();
            return new
            {
                storageCode = g.Key,
                paymentCount = g.Count(),
                totalVehicles = sLines.Count,
                totalAmount = g.Sum(x => x.TotalAmountAfterVAT)
            };
        }).OrderByDescending(x => x.totalAmount).ToList();

        var byPeriodMonth = payments.GroupBy(p => p.PeriodMonth).Select(g =>
        {
            var pIds = g.Select(x => x.Id).ToList();
            var mLines = lines.Where(l => pIds.Contains(l.PdiPaymentId) && l.Status != "Cancelled").ToList();
            return new
            {
                periodMonth = g.Key,
                paymentCount = g.Count(),
                totalVehicles = mLines.Count,
                totalAmount = g.Sum(x => x.TotalAmountAfterVAT)
            };
        }).OrderByDescending(x => x.periodMonth).ToList();

        return new
        {
            totalPayments,
            totalDraft,
            totalSubmitted,
            totalApproved1,
            totalApproved2,
            totalTCMSSigned,
            totalSettled,
            totalCancelled,
            totalVehicleCount,
            totalCostIn,
            totalCostOut,
            totalAmount,
            totalVatAmount,
            totalAmountAfterVAT,
            settlementRatePercent,
            byDealer,
            byStorage,
            byPeriodMonth
        };
    }

    // ===== Chính sách hỗ trợ bán lẻ xe ô tô cho Đại lý & Quyết toán hỗ trợ theo VIN (BizHTC.DealerSales / SPL_SalesPolicyMst & SPL_SPSupportRetail) =====

    public async Task<object> CreateSalesPolicyAsync(CreateSalesPolicyDto dto)
    {
        if (string.IsNullOrWhiteSpace(dto.SPNo))
            throw new InvalidOperationException("Cần số hiệu văn bản chính sách SPNo.");
        if (dto.EndDate < dto.StartDate)
            throw new InvalidOperationException("Ngày kết thúc EndDate không được trước ngày bắt đầu StartDate.");

        var spsrCode = string.IsNullOrWhiteSpace(dto.SPSRCode)
            ? "SPL-" + DateTime.Now.ToString("yyyyMMdd-HHmmss")
            : dto.SPSRCode!.Trim().ToUpperInvariant();

        if (await db.SalesPolicies.AnyAsync(p => p.OrgId == Org && p.SPSRCode == spsrCode))
            throw new InvalidOperationException($"Mã chính sách {spsrCode} đã tồn tại.");

        var policy = new SalesPolicy
        {
            OrgId = Org,
            SPSRCode = spsrCode,
            SPNo = dto.SPNo.Trim(),
            SPSRType = string.IsNullOrWhiteSpace(dto.SPSRType) ? "RetailSupport" : dto.SPSRType.Trim(),
            SPSRRoot = dto.SPSRRoot?.Trim(),
            FormBusinessSupportCode = string.IsNullOrWhiteSpace(dto.FormBusinessSupportCode) ? "DirectCash" : dto.FormBusinessSupportCode.Trim(),
            StartDate = dto.StartDate,
            EndDate = dto.EndDate,
            TotalModelsCount = dto.Lines?.Count ?? 0,
            TotalSupportBudget = dto.TotalSupportBudget ?? 0,
            TotalVinApplied = 0,
            TotalActualPaidAmount = 0,
            FilePath = dto.FilePath?.Trim(),
            Status = "Draft",
            Remark = dto.Remark?.Trim(),
            CreatedBy = dto.CreatedBy?.Trim(),
            CreatedAt = DateTime.Now
        };

        db.SalesPolicies.Add(policy);
        await db.SaveChangesAsync();

        if (dto.Lines != null && dto.Lines.Count > 0)
        {
            int idx = 1;
            foreach (var item in dto.Lines)
            {
                if (string.IsNullOrWhiteSpace(item.Model))
                    throw new InvalidOperationException("Mỗi dòng chính sách cần có Model xe.");

                db.SalesPolicyLines.Add(new SalesPolicyLine
                {
                    OrgId = Org,
                    SalesPolicyId = policy.Id,
                    SPSRCode = spsrCode,
                    LineIndex = idx++,
                    Model = item.Model.Trim(),
                    SpecCode = item.SpecCode?.Trim() ?? "",
                    SpecDescription = item.SpecDescription?.Trim(),
                    DealerCode = item.DealerCode?.Trim(),
                    ModelYear = item.ModelYear ?? 2026,
                    AmountSupport = item.AmountSupport,
                    Status = "Active",
                    Remark = item.Remark?.Trim()
                });
            }
            await db.SaveChangesAsync();
        }

        return new
        {
            policy.SPSRCode,
            policy.SPNo,
            policy.SPSRType,
            policy.FormBusinessSupportCode,
            policy.StartDate,
            policy.EndDate,
            policy.TotalModelsCount,
            policy.TotalSupportBudget,
            policy.Status,
            policy.CreatedAt
        };
    }

    public async Task<object> ListSalesPoliciesAsync(string? status, string? spsrType, string? q)
    {
        var query = db.SalesPolicies.Where(p => p.OrgId == Org);
        if (!string.IsNullOrWhiteSpace(status)) query = query.Where(p => p.Status == status);
        if (!string.IsNullOrWhiteSpace(spsrType)) query = query.Where(p => p.SPSRType == spsrType);
        if (!string.IsNullOrWhiteSpace(q))
        {
            var search = q.Trim().ToLowerInvariant();
            query = query.Where(p => p.SPSRCode.ToLower().Contains(search) || p.SPNo.ToLower().Contains(search) || (p.Remark != null && p.Remark.ToLower().Contains(search)));
        }

        var list = await query.OrderByDescending(p => p.Id).ToListAsync();

        var now = DateTime.Now;
        foreach (var p in list)
        {
            if (p.Status == "Active" && p.EndDate < now)
            {
                p.Status = "Expired";
            }
        }
        await db.SaveChangesAsync();

        var policyIds = list.Select(p => p.Id).ToList();
        var linesCountDict = await db.SalesPolicyLines
            .Where(l => l.OrgId == Org && policyIds.Contains(l.SalesPolicyId))
            .GroupBy(l => l.SalesPolicyId)
            .ToDictionaryAsync(g => g.Key, g => g.Count());

        var items = list.Select(p => new
        {
            p.Id,
            p.SPSRCode,
            p.SPNo,
            p.SPSRType,
            p.SPSRRoot,
            p.FormBusinessSupportCode,
            p.StartDate,
            p.EndDate,
            TotalModelsCount = linesCountDict.TryGetValue(p.Id, out var c) ? c : p.TotalModelsCount,
            p.TotalSupportBudget,
            p.TotalVinApplied,
            p.TotalActualPaidAmount,
            p.FilePath,
            p.Status,
            p.Remark,
            p.CreatedBy,
            p.CreatedAt,
            p.ApprovedBy,
            p.ApprovedAt,
            p.SuspendedBy,
            p.SuspendedAt,
            p.CancelledBy,
            p.CancelledAt,
            p.CancelReason
        }).ToList();

        return new { count = items.Count, items };
    }

    public async Task<object?> GetSalesPolicyAsync(string spsrCode)
    {
        spsrCode = spsrCode.Trim().ToUpperInvariant();
        var policy = await db.SalesPolicies.FirstOrDefaultAsync(p => p.OrgId == Org && p.SPSRCode == spsrCode);
        if (policy is null) return null;

        if (policy.Status == "Active" && policy.EndDate < DateTime.Now)
        {
            policy.Status = "Expired";
            await db.SaveChangesAsync();
        }

        var lines = await db.SalesPolicyLines
            .Where(l => l.OrgId == Org && l.SalesPolicyId == policy.Id)
            .OrderBy(l => l.LineIndex)
            .ToListAsync();

        var supportsCount = await db.SalesPolicySupports
            .CountAsync(s => s.OrgId == Org && s.SPSRCode == spsrCode && s.Status != "Cancelled");

        var actualPaid = await db.SalesPolicySupports
            .Where(s => s.OrgId == Org && s.SPSRCode == spsrCode && s.Status == "Settled")
            .SumAsync(s => s.AmountSupport);

        return new
        {
            policy.Id,
            policy.SPSRCode,
            policy.SPNo,
            policy.SPSRType,
            policy.SPSRRoot,
            policy.FormBusinessSupportCode,
            policy.StartDate,
            policy.EndDate,
            TotalModelsCount = lines.Count,
            policy.TotalSupportBudget,
            TotalVinApplied = supportsCount,
            TotalActualPaidAmount = actualPaid,
            policy.FilePath,
            policy.Status,
            policy.Remark,
            policy.CreatedBy,
            policy.CreatedAt,
            policy.ApprovedBy,
            policy.ApprovedAt,
            policy.SuspendedBy,
            policy.SuspendedAt,
            policy.CancelledBy,
            policy.CancelledAt,
            policy.CancelReason,
            lines = lines.Select(l => new
            {
                l.Id,
                l.LineIndex,
                l.Model,
                l.SpecCode,
                l.SpecDescription,
                l.DealerCode,
                l.ModelYear,
                l.AmountSupport,
                l.Status,
                l.Remark
            })
        };
    }

    public async Task<object?> UpdateSalesPolicyHeaderAsync(string spsrCode, UpdateSalesPolicyHeaderDto dto)
    {
        spsrCode = spsrCode.Trim().ToUpperInvariant();
        var policy = await db.SalesPolicies.FirstOrDefaultAsync(p => p.OrgId == Org && p.SPSRCode == spsrCode);
        if (policy is null) return null;

        if (policy.Status is "Cancelled" or "Expired")
            throw new InvalidOperationException($"Không thể sửa chính sách đang ở trạng thái {policy.Status}.");

        if (!string.IsNullOrWhiteSpace(dto.SPNo)) policy.SPNo = dto.SPNo.Trim();
        if (!string.IsNullOrWhiteSpace(dto.SPSRType)) policy.SPSRType = dto.SPSRType.Trim();
        if (dto.SPSRRoot != null) policy.SPSRRoot = dto.SPSRRoot.Trim();
        if (!string.IsNullOrWhiteSpace(dto.FormBusinessSupportCode)) policy.FormBusinessSupportCode = dto.FormBusinessSupportCode.Trim();
        if (dto.StartDate.HasValue) policy.StartDate = dto.StartDate.Value;
        if (dto.EndDate.HasValue) policy.EndDate = dto.EndDate.Value;
        if (dto.TotalSupportBudget.HasValue) policy.TotalSupportBudget = dto.TotalSupportBudget.Value;
        if (dto.FilePath != null) policy.FilePath = dto.FilePath.Trim();
        if (dto.Remark != null) policy.Remark = dto.Remark.Trim();

        await db.SaveChangesAsync();
        return new { policy.SPSRCode, policy.SPNo, policy.Status, message = "Cập nhật thông tin chính sách thành công." };
    }

    public async Task<object?> SalesPolicyTransitionAsync(string spsrCode, string action, SalesPolicyTransitionDto? dto)
    {
        spsrCode = spsrCode.Trim().ToUpperInvariant();
        var policy = await db.SalesPolicies.FirstOrDefaultAsync(p => p.OrgId == Org && p.SPSRCode == spsrCode);
        if (policy is null) return null;

        var act = action.Trim().ToLowerInvariant();
        var now = dto?.TransitionDate ?? DateTime.Now;

        switch (act)
        {
            case "approve" or "activate" or "active":
                if (policy.Status is not ("Draft" or "Suspended")) return null;
                policy.Status = "Active";
                policy.ApprovedBy = dto?.Actor?.Trim() ?? "SalesDirector";
                policy.ApprovedAt = now;
                break;

            case "suspend":
                if (policy.Status != "Active") return null;
                policy.Status = "Suspended";
                policy.SuspendedBy = dto?.Actor?.Trim() ?? "SalesManager";
                policy.SuspendedAt = now;
                break;

            case "expire":
                if (policy.Status != "Active") return null;
                policy.Status = "Expired";
                break;

            case "cancel":
                if (policy.Status is "Cancelled") return null;
                policy.Status = "Cancelled";
                policy.CancelledBy = dto?.Actor?.Trim() ?? "SalesDirector";
                policy.CancelledAt = now;
                policy.CancelReason = dto?.Reason?.Trim() ?? dto?.Note?.Trim();
                break;

            default:
                return null;
        }

        if (!string.IsNullOrWhiteSpace(dto?.Note))
            policy.Remark = string.IsNullOrWhiteSpace(policy.Remark) ? dto.Note : $"{policy.Remark} | {act}: {dto.Note}";

        await db.SaveChangesAsync();
        return new { policy.SPSRCode, status = policy.Status, policy.ApprovedAt, policy.SuspendedAt, policy.CancelledAt };
    }

    public async Task<object?> AddSalesPolicyLinesAsync(string spsrCode, List<SalesPolicyLineInputDto> items)
    {
        spsrCode = spsrCode.Trim().ToUpperInvariant();
        var policy = await db.SalesPolicies.FirstOrDefaultAsync(p => p.OrgId == Org && p.SPSRCode == spsrCode);
        if (policy is null) return null;

        if (policy.Status is "Cancelled" or "Expired")
            throw new InvalidOperationException($"Không thể thêm dòng vào chính sách đang ở trạng thái {policy.Status}.");

        var maxIdx = await db.SalesPolicyLines
            .Where(l => l.OrgId == Org && l.SalesPolicyId == policy.Id)
            .MaxAsync(l => (int?)l.LineIndex) ?? 0;

        var addedLines = new List<SalesPolicyLine>();
        foreach (var item in items)
        {
            if (string.IsNullOrWhiteSpace(item.Model))
                throw new InvalidOperationException("Mỗi dòng chính sách cần có Model xe.");

            var line = new SalesPolicyLine
            {
                OrgId = Org,
                SalesPolicyId = policy.Id,
                SPSRCode = spsrCode,
                LineIndex = ++maxIdx,
                Model = item.Model.Trim(),
                SpecCode = item.SpecCode?.Trim() ?? "",
                SpecDescription = item.SpecDescription?.Trim(),
                DealerCode = item.DealerCode?.Trim(),
                ModelYear = item.ModelYear ?? 2026,
                AmountSupport = item.AmountSupport,
                Status = "Active",
                Remark = item.Remark?.Trim()
            };
            db.SalesPolicyLines.Add(line);
            addedLines.Add(line);
        }

        policy.TotalModelsCount += items.Count;
        await db.SaveChangesAsync();

        return new
        {
            policy.SPSRCode,
            addedCount = addedLines.Count,
            totalModelsCount = policy.TotalModelsCount,
            lines = addedLines.Select(l => new { l.Id, l.LineIndex, l.Model, l.SpecCode, l.AmountSupport })
        };
    }

    public async Task<object?> UpdateSalesPolicyLineAsync(string spsrCode, long lineId, UpdateSalesPolicyLineDto dto)
    {
        spsrCode = spsrCode.Trim().ToUpperInvariant();
        var line = await db.SalesPolicyLines.FirstOrDefaultAsync(l => l.OrgId == Org && l.Id == lineId && l.SPSRCode == spsrCode);
        if (line is null) return null;

        if (!string.IsNullOrWhiteSpace(dto.Model)) line.Model = dto.Model.Trim();
        if (dto.SpecCode != null) line.SpecCode = dto.SpecCode.Trim();
        if (dto.SpecDescription != null) line.SpecDescription = dto.SpecDescription.Trim();
        if (dto.DealerCode != null) line.DealerCode = dto.DealerCode.Trim();
        if (dto.ModelYear.HasValue) line.ModelYear = dto.ModelYear.Value;
        if (dto.AmountSupport.HasValue) line.AmountSupport = dto.AmountSupport.Value;
        if (!string.IsNullOrWhiteSpace(dto.Status)) line.Status = dto.Status.Trim();
        if (dto.Remark != null) line.Remark = dto.Remark.Trim();

        await db.SaveChangesAsync();
        return new { line.Id, line.SPSRCode, line.Model, line.SpecCode, line.AmountSupport, line.Status, message = "Cập nhật dòng chính sách thành công." };
    }

    public async Task<object?> RemoveSalesPolicyLineAsync(string spsrCode, long lineId)
    {
        spsrCode = spsrCode.Trim().ToUpperInvariant();
        var line = await db.SalesPolicyLines.FirstOrDefaultAsync(l => l.OrgId == Org && l.Id == lineId && l.SPSRCode == spsrCode);
        if (line is null) return null;

        var policy = await db.SalesPolicies.FirstOrDefaultAsync(p => p.OrgId == Org && p.Id == line.SalesPolicyId);

        db.SalesPolicyLines.Remove(line);
        if (policy != null && policy.TotalModelsCount > 0) policy.TotalModelsCount--;

        await db.SaveChangesAsync();
        return new { lineId, spsrCode, message = "Đã xóa dòng chính sách thành công." };
    }

    public async Task<object> CreateSalesPolicySupportAsync(CreateSalesPolicySupportDto dto)
    {
        if (string.IsNullOrWhiteSpace(dto.SPSRCode))
            throw new InvalidOperationException("Cần mã chính sách hỗ trợ SPSRCode.");
        if (string.IsNullOrWhiteSpace(dto.Vin))
            throw new InvalidOperationException("Cần số khung xe VIN để lập đề nghị hỗ trợ.");

        var vin = dto.Vin.Trim().ToUpperInvariant();
        var vehicle = await db.Vehicles.FirstOrDefaultAsync(v => v.OrgId == Org && v.Vin == vin);
        if (vehicle is null)
            throw new InvalidOperationException($"Không tìm thấy số khung VIN {vin} trong hệ thống.");

        var spsrCode = dto.SPSRCode.Trim().ToUpperInvariant();
        var policy = await db.SalesPolicies.FirstOrDefaultAsync(p => p.OrgId == Org && p.SPSRCode == spsrCode);
        if (policy is null)
            throw new InvalidOperationException($"Không tìm thấy chính sách {spsrCode}.");

        if (policy.Status is "Cancelled")
            throw new InvalidOperationException($"Chính sách {spsrCode} đã bị hủy.");

        var existingSupport = await db.SalesPolicySupports
            .FirstOrDefaultAsync(s => s.OrgId == Org && s.Vin == vin && s.SPSRCode == spsrCode && s.Status != "Cancelled" && s.Status != "Rejected");
        if (existingSupport != null)
            throw new InvalidOperationException($"Xe VIN {vin} đã có hồ sơ hỗ trợ {existingSupport.SupportNo} thuộc chính sách {spsrCode}.");

        var policyLines = await db.SalesPolicyLines
            .Where(l => l.OrgId == Org && l.SalesPolicyId == policy.Id && l.Status == "Active")
            .ToListAsync();

        var matchedLine = policyLines.FirstOrDefault(l => vehicle.Model.Contains(l.Model, StringComparison.OrdinalIgnoreCase))
            ?? policyLines.FirstOrDefault();

        decimal amountSupport = dto.AmountSupport ?? matchedLine?.AmountSupport ?? 0;
        if (amountSupport <= 0 && matchedLine != null) amountSupport = matchedLine.AmountSupport;

        var supportNo = string.IsNullOrWhiteSpace(dto.SupportNo)
            ? "SPSR-" + DateTime.Now.ToString("yyyyMMdd-HHmmss")
            : dto.SupportNo.Trim().ToUpperInvariant();

        if (await db.SalesPolicySupports.AnyAsync(s => s.OrgId == Org && s.SupportNo == supportNo))
            throw new InvalidOperationException($"Mã phiếu hỗ trợ {supportNo} đã tồn tại.");

        var support = new SalesPolicySupport
        {
            OrgId = Org,
            SupportNo = supportNo,
            SPSRCode = spsrCode,
            SPNo = policy.SPNo,
            Vin = vin,
            DealerCode = dto.DealerCode?.Trim() ?? vehicle.DealerCode ?? "DLR-OEM",
            DealerName = dto.DealerName?.Trim(),
            Model = vehicle.Model,
            SpecCode = matchedLine?.SpecCode ?? "",
            EngineNo = vehicle.EngineNo,
            Color = vehicle.Color,
            DateSupport = dto.DateSupport ?? DateTime.Now,
            DateFullStatus = dto.DateFullStatus ?? (vehicle.DeliveredAt ?? DateTime.Now),
            AmountSupport = amountSupport,
            HTCInvoiceNo = dto.HTCInvoiceNo?.Trim() ?? vehicle.InvoiceNo,
            HTCInvoiceDate = dto.HTCInvoiceDate ?? vehicle.InvoiceDate,
            Status = "Draft",
            Remark = dto.Remark?.Trim(),
            CreatedBy = dto.CreatedBy?.Trim(),
            CreatedAt = DateTime.Now
        };

        db.SalesPolicySupports.Add(support);
        policy.TotalVinApplied++;

        Log(vin, "SalesPolicySupportCreated", $"{supportNo} Đề nghị hỗ trợ bán lẻ theo chính sách {spsrCode} mức {amountSupport:N0} VNĐ");

        await db.SaveChangesAsync();

        return new
        {
            support.SupportNo,
            support.SPSRCode,
            support.SPNo,
            support.Vin,
            support.DealerCode,
            support.Model,
            support.AmountSupport,
            support.Status,
            support.CreatedAt
        };
    }

    public async Task<object> BatchAssignPolicySupportVinsAsync(BatchAssignPolicySupportDto dto)
    {
        if (string.IsNullOrWhiteSpace(dto.SPSRCode))
            throw new InvalidOperationException("Cần mã chính sách hỗ trợ SPSRCode.");
        if (dto.Vins is null || dto.Vins.Count == 0)
            throw new InvalidOperationException("Cần danh sách số khung VINs để gán hỗ trợ.");

        var spsrCode = dto.SPSRCode.Trim().ToUpperInvariant();
        var policy = await db.SalesPolicies.FirstOrDefaultAsync(p => p.OrgId == Org && p.SPSRCode == spsrCode);
        if (policy is null)
            throw new InvalidOperationException($"Không tìm thấy chính sách {spsrCode}.");

        var policyLines = await db.SalesPolicyLines
            .Where(l => l.OrgId == Org && l.SalesPolicyId == policy.Id && l.Status == "Active")
            .ToListAsync();

        var distinctVins = dto.Vins.Select(v => v.Trim().ToUpperInvariant()).Distinct().ToList();
        var vehicles = await db.Vehicles.Where(v => v.OrgId == Org && distinctVins.Contains(v.Vin)).ToListAsync();
        var vDict = vehicles.ToDictionary(v => v.Vin);

        var existingSupports = await db.SalesPolicySupports
            .Where(s => s.OrgId == Org && distinctVins.Contains(s.Vin) && s.SPSRCode == spsrCode && s.Status != "Cancelled" && s.Status != "Rejected")
            .Select(s => s.Vin)
            .ToListAsync();

        var createdList = new List<SalesPolicySupport>();
        int seq = 1;
        var now = DateTime.Now;

        foreach (var vin in distinctVins)
        {
            if (!vDict.TryGetValue(vin, out var v)) continue;
            if (existingSupports.Contains(vin)) continue;

            var matchedLine = policyLines.FirstOrDefault(l => v.Model.Contains(l.Model, StringComparison.OrdinalIgnoreCase))
                ?? policyLines.FirstOrDefault();

            decimal amount = matchedLine?.AmountSupport ?? 0;
            var sNo = $"SPSR-{now:yyyyMMddHHmmss}-{seq++:D3}";

            var supp = new SalesPolicySupport
            {
                OrgId = Org,
                SupportNo = sNo,
                SPSRCode = spsrCode,
                SPNo = policy.SPNo,
                Vin = vin,
                DealerCode = dto.DealerCode?.Trim() ?? v.DealerCode ?? "DLR-OEM",
                Model = v.Model,
                SpecCode = matchedLine?.SpecCode ?? "",
                EngineNo = v.EngineNo,
                Color = v.Color,
                DateSupport = dto.DateSupport ?? now,
                DateFullStatus = dto.DateFullStatus ?? (v.DeliveredAt ?? now),
                AmountSupport = amount,
                HTCInvoiceNo = v.InvoiceNo,
                HTCInvoiceDate = v.InvoiceDate,
                Status = "Draft",
                Remark = dto.Remark?.Trim(),
                CreatedBy = dto.CreatedBy?.Trim(),
                CreatedAt = now
            };

            db.SalesPolicySupports.Add(supp);
            createdList.Add(supp);
            Log(vin, "SalesPolicySupportCreated", $"{sNo} Gán hỗ trợ bán lẻ chính sách {spsrCode} mức {amount:N0} VNĐ");
        }

        policy.TotalVinApplied += createdList.Count;
        await db.SaveChangesAsync();

        return new
        {
            policy.SPSRCode,
            policy.SPNo,
            totalRequested = distinctVins.Count,
            assignedCount = createdList.Count,
            skippedCount = distinctVins.Count - createdList.Count,
            items = createdList.Select(s => new { s.SupportNo, s.Vin, s.Model, s.AmountSupport, s.DealerCode })
        };
    }

    public async Task<object> ListSalesPolicySupportsAsync(string? status, string? dealer, string? spsrCode, string? vin, string? supportNo)
    {
        var q = db.SalesPolicySupports.Where(s => s.OrgId == Org);
        if (!string.IsNullOrWhiteSpace(status)) q = q.Where(s => s.Status == status);
        if (!string.IsNullOrWhiteSpace(dealer)) q = q.Where(s => s.DealerCode == dealer);
        if (!string.IsNullOrWhiteSpace(spsrCode)) q = q.Where(s => s.SPSRCode == spsrCode.Trim().ToUpperInvariant());
        if (!string.IsNullOrWhiteSpace(vin)) q = q.Where(s => s.Vin == vin.Trim().ToUpperInvariant());
        if (!string.IsNullOrWhiteSpace(supportNo)) q = q.Where(s => s.SupportNo == supportNo.Trim().ToUpperInvariant());

        var items = await q.OrderByDescending(s => s.Id).Take(500).Select(s => new
        {
