            db.GpsInstallationLines.Add(new GpsInstallationLine
            {
                OrgId = Org,
                GpsInstallationId = install.Id,
                GpsInNo = gpsInNo,
                LineIndex = nextIdx++,
                Vin = vin,
                Model = v?.Model ?? "N/A",
                EngineNo = v?.EngineNo,
                Color = v?.Color,
                StorageCode = it.StorageCode?.Trim() ?? v?.StorageCode,
                GpsCode = gpsCode,
                ImeiNo = d?.ImeiNo,
